(()=>{document.documentElement.style.setProperty('--orange','#f26a32');document.querySelector('#searchToggle')?.remove();const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const defaults=[{"id":"1","title":"EPS mi taş yünü mü? Projeniz için doğru seçim.","category":"YALITIM","excerpt":"Dış cephe mantolamasında yalıtım malzemesi seçerken nelere dikkat etmeli?","content":"EPS (Genleştirilmiş Polistiren) ve Taş Yünü, dış cephe ısı yalıtımında (mantolama) en sık kullanılan iki ana malzemedir. Peki projeniz için hangisi daha uygun? İşte karar vermenizi sağlayacak teknik detaylar:\n\n1. Isı Yalıtım Performansı\nHer iki malzemenin de ısı iletkenlik katsayısı (lambda değeri) birbirine oldukça yakındır (genellikle 0.035 - 0.040 W/mK arası). Ancak EPS'nin karbon takviyeli (Karbonlu EPS) versiyonları, ısı yalıtımı konusunda standart taş yününe kıyasla %10-15 daha iyi performans gösterebilir.\n\n2. Yangın Dayanımı (En Kritik Fark)\nTaş yünü, A1 sınıfı hiç yanmaz malzeme kategorisindedir. Yangın anında alevleri iletmez ve 1000°C sıcaklığa kadar dayanıklıdır. Yüksek katlı binalarda (özellikle 21.5 metreyi aşan yapılarda) ve kamu binalarında taş yünü kullanımı yasal bir zorunluluktur. EPS ise B1 (zor alev alan) veya E sınıfı olabilir ve yangın anında eriyerek zehirli gaz salınımına neden olabilir.\n\n3. Ses Yalıtımı ve Nefes Alma\nTaş yünü lifli yapısı sayesinde mükemmel bir ses yalıtımı sağlar ve binanın nefes almasına (su buharı geçirgenliği) büyük ölçüde yardımcı olur. EPS ise kapalı hücreli yapısı gereği ses yalıtımında zayıftır ve buhar geçirgenliği taş yününe göre daha düşüktür.\n\n4. Maliyet ve Uygulama Kolaylığı\nEPS, taş yününe göre çok daha hafiftir. Bu durum hem nakliye hem de cepheye uygulanmasını inanılmaz derecede kolaylaştırır. Malzeme ve işçilik maliyeti olarak EPS, taş yününe kıyasla %30-40 daha ekonomiktir. Taş yününün ağırlığı, cepheye daha fazla dübel atılmasını ve daha güçlü yapıştırıcı kullanılmasını gerektirir.\n\nÖzetle;\nEğer bütçeniz kısıtlıysa ve müstakil/az katlı bir yapınız varsa Karbonlu EPS harika bir fiyat/performans ürünüdür. Ancak bütçe sorununuz yoksa, binanız yüksek katlıysa veya yangın güvenliği/ses yalıtımı sizin için ön plandaysa kesinlikle Taş Yünü tercih etmelisiniz.","image":"assets/blog_yalitim.jpg","date":"10 Ekim 2026","tags":"yalitim, eps, tasyunu, mantolama"},{"id":"2","title":"1 torba seramik yapıştırıcısı kaç m² gider?","category":"SERAMİK","excerpt":"Seramik yapıştırıcısı tüketimini etkileyen faktörler ve pratik hesaplamalar.","content":"Şantiyelerde ve ev tadilatlarında seramik ustalarının ve mal sahiplerinin en çok sorduğu sorulardan biri: \"Bir torba yapıştırıcı ile kaç metrekare yer yapabiliriz?\"\n\nStandart bir seramik yapıştırıcısı torbası 25 kg'dır. Ortalama ve ideal şartlar altında 25 kg'lık bir torba ile 4 ila 5 m² arası seramik kaplanabilir. Yani sarfiyat ortalama 5 kg/m²'dir. Ancak bu rakam teoriktir ve sahada birçok faktöre göre değişiklik gösterir:\n\n1. Zeminin Düzgünlüğü (Şap veya Sıva Kalitesi)\nTüketimi etkileyen en büyük faktör zemindir. Eğer zemin teraziye alınmış, pürüzsüz ve iyi atılmış bir şap ise tüketim 4 kg/m² seviyelerine kadar düşebilir. Ancak zemin bozuk, dalgalı veya meyil hatalıysa, usta bu hataları yapıştırıcı ile \"doldurarak\" (kalın diş çekerek) gidermek zorunda kalacaktır. Bu durumda sarfiyat 7-8 kg/m²'ye kadar çıkabilir.\n\n2. Seramik Ebatları ve Çift Yönlü Sürme\nGünümüzde 60x120 cm, 80x80 cm gibi büyük ebatlı seramikler (granitler) çok popülerdir. Bu büyük ebatların sağlıklı yapışması ve ortasında boşluk kalıp kırılmaması için yapıştırıcının hem zemine hem de seramiğin arkasına sürülmesi gerekir (Çift sürme tekniği). Çift sürme yapıldığında sarfiyat anında artar ve 25 kg'lık bir torba sadece 3 m² alanı ancak kaplar.\n\n3. Kullanılan Tarak (Mala) Diş Boyutu\nKüçük ebatlı (33x33) seramiklerde 6 mm veya 8 mm dişli mala kullanılırken, büyük ebatlı granitlerde 10 mm, 12 mm veya yarım ay dişli malalar kullanılır. Diş boyutu büyüdükçe yüzeyde kalan yapıştırıcı miktarı artar ve torbanın kaplayacağı metrekare düşer.\n\nKısacası planlama yaparken; standart ebatlar (60x60 vb.) ve düzgün bir zemin için torba başı 4.5 m²; büyük ebatlı granitler (60x120) ve çift sürme uygulanacak yerler için torba başı 3 m² olarak hesaplama yapmak en güvenli yoldur.","image":"assets/blog_seramik.jpg","date":"08 Ekim 2026","tags":"seramik, yapistirici, metraj, hesaplama"},{"id":"3","title":"Ev tadilatında bütçeyi kontrol altında tutmanın 6 yolu.","category":"TADİLAT","excerpt":"Beklenmedik maliyetleri önleyin ve projenizi planladığınız bütçede bitirin.","content":"Tadilat projelerinin en korkutucu yanı, işe başlarken öngörülen bütçenin inşaat sürecinde iki, hatta üç katına çıkmasıdır. Bu durum genellikle plansızlıktan kaynaklanır. İşte bütçenizi korumanızı sağlayacak 6 altın kural:\n\n1. İhtiyaç Listenizi ve Kapsamı İşe Başlamadan Netleştirin\n\"Usta gelmişken şu duvarı da kıralım\", \"Banyoyu yapmışken koridoru da seramik yapalım\" cümleleri bütçenin en büyük düşmanıdır. İşe başlamadan önce nelerin yapılacağını madde madde yazın ve inşaat sırasında bu kapsamın dışına çıkmamaya özen gösterin.\n\n2. Malzemeleri Önceden Seçin ve Sabitleyin\nMaliyet artışlarının büyük kısmı, başlangıçta orta segment düşünülen seramiklerin, mağazaya gidildiğinde çok beğenilip pahalı ithal ürünlerle değiştirilmesinden kaynaklanır. Vitrifiye, seramik, parke ve armatür gibi kalemleri proje başlamadan önce seçin ve fiyatlarını bütçenize sabitleyin.\n\n3. %15 Acil Durum (Sürpriz) Payı Bırakın\nTadilat, özellikle eski binalarda her zaman sürprizlere gebedir. Fayanslar kırıldığında altından çürümüş su tesisatı çıkabilir veya asma tavan söküldüğünde elektrik tesisatının tamamen yenilenmesi gerektiği anlaşılabilir. Toplam bütçenizin en az %10-15'ini bu görünmez giderler için kenarda tutun.\n\n4. Doğru ve Detaylı Bir Keşif Yaptırın\nSadece göz kararı veya m² üzerinden verilen \"götürü\" fiyatlara güvenmeyin. Hangi markanın hangi modelinin kullanılacağını, kaç kat boya sürüleceğini, moloz atımının kime ait olacağını kalem kalem belirten detaylı bir keşif özeti isteyin.\n\n5. Kesinlikle Yazılı Bir Sözleşme Yapın\nUygulamacı firma veya ustalarınızla mutlaka işin süresini, kullanılacak malzemelerin niteliğini (marka/model belirterek), ödeme planını ve olası gecikme cezalarını içeren yazılı bir sözleşme yapın. Ödemelerinizi işin ilerleme durumuna göre planlayın; işin başında büyük meblağlar peşin ödemekten kaçının.\n\n6. PROKONT Akıllı Planlayıcı'yı Kullanın\nSitemizde yer alan Akıllı Proje Planlayıcı aracı, güncel ve resmi piyasa fiyatları (2026 Poz Listesi) üzerinden size en gerçekçi maliyet tablosunu saniyeler içinde sunar. Bu sayede ustadan alacağınız fiyatların piyasa rayicinde olup olmadığını kolayca kontrol edebilirsiniz.","image":"assets/blog_tadilat.jpg","date":"05 Ekim 2026","tags":"tadilat, butce, maliyet, planlama"},{"id":"4","title":"Banyo tadilatında su yalıtımı neden hayati önem taşır?","category":"TADİLAT","excerpt":"Görünmeyen ama en kritik aşama: Banyolarda su yalıtımı nasıl yapılmalı?","content":"Banyo tadilatı yaparken genellikle fayansların rengine, vitrifiye ürünlerine ve armatürlerin tasarımına odaklanılır. Ancak bir banyonun gerçek kalitesi ve ömrü, fayansın altında yatan su yalıtımı (izolasyon) ile ölçülür.\n\n1. Alt Kata Su Sızmasını Önler\nEn sık karşılaşılan sorunlardan biri, banyo zemininden alt komşunun tavanına su sızmasıdır. Seramik aralarındaki derzler zamanla aşınır ve suyu alta geçirir. Seramik öncesi sürülen çift kompenantlı sürme su yalıtımı, bu sızıntıyı %100 engeller.\n\n2. Duvarlarda Nem ve Küfü Engeller\nÖzellikle duşakabin içindeki duvarlar sürekli suya maruz kalır. Sadece zemine değil, duş alanındaki duvarlara da en az 1.5 metre yüksekliğe kadar su yalıtımı yapılmalıdır. Aksi takdirde yan odanın duvarlarında kabarmalar ve siyah küfler oluşur.\n\n3. Pah Bantlarının Kullanımı\nSu yalıtımında en zayıf noktalar duvar ve zeminin birleştiği köşe noktalarıdır. Kaliteli bir tadilatta bu köşelere esnek 'pah bantları' uygulanır ve suyun köşelerden sızması engellenir.\n\nSonuç olarak; banyo tadilatında seramiklere harcayacağınız bütçenin küçük bir kısmını kaliteli bir su yalıtımına ayırmak, sizi ileride oluşabilecek on binlerce liralık kırım döküm masrafından kurtaracaktır.","image":"assets/blog_suyalitimi.jpg","date":"12 Ekim 2026","tags":"banyo, tadilat, su yalitimi, izolasyon"},{"id":"5","title":"Laminat Parke mi Lamine Parke mi? Hangisini Seçmeli?","category":"ZEMİN","excerpt":"İsimleri benzeyen ama yapıları tamamen farklı olan bu iki parke türünün farkları.","content":"Zemin kaplamalarında en çok karıştırılan iki malzeme laminat parke ve lamine parkedir. İsimleri birbirine benzese de, malzeme yapısı, fiyatı ve kullanım ömrü açısından tamamen farklı iki üründür.\n\n1. Laminat Parke Nedir?\nLaminat parke, preslenmiş ahşap tozunun (MDF/HDF) üzerine ahşap desenli bir kağıt basılması ve en üste koruyucu bir tabaka (melamin) çekilmesiyle üretilir. Yani üst yüzeyi gerçek ahşap değil, fotoğraftır.\nAvantajları: Çok ekonomiktir, çizilmelere karşı son derece dayanıklıdır, montajı çok hızlıdır.\nDezavantajları: Suya karşı hassastır, yapay bir his verir ve ömrü lamineye göre daha kısadır.\n\n2. Lamine Parke Nedir?\nLamine parke %100 gerçek ahşaptan üretilir. Genellikle alt katmanlarda daha ucuz ahşaplar, en üstteki 3-4 mm'lik yüzeyde ise meşe, ceviz gibi değerli ağaçlar kullanılır.\nAvantajları: Tamamen doğaldır, basıldığında sıcak bir his verir. Yıllar sonra çizildiğinde sistre (zımpara) ve cila yapılarak ilk günkü haline döndürülebilir.\nDezavantajları: Laminat parkeye göre 3-4 kat daha pahalıdır, çizilmelere karşı daha hassastır.\n\nEğer yoğun kullanılan, çocuklu bir eviniz varsa ve bütçenizi zorlamak istemiyorsanız 8mm veya 10mm 32. sınıf bir Laminat parke işinizi fazlasıyla görecektir. Ancak doğal bir görünüm arıyor ve uzun ömürlü, prestijli bir zemin istiyorsanız tercihiniz Lamine parke olmalıdır.","image":"assets/blog_parke.jpg","date":"15 Ekim 2026","tags":"parke, laminat, lamine, zemin"},{"id":"6","title":"Boya badana yaparken sarfiyat hesabı nasıl yapılır?","category":"BOYA","excerpt":"15 litrelik bir kova boya ile kaç metrekare duvar boyanabilir?","content":"Bir odayı boyarken doğru rengi seçmek kadar, ne kadar boya gideceğini doğru hesaplamak da önemlidir. Gereğinden az boya almak işin yarım kalmasına, fazla almak ise israfa neden olur.\n\nİşte pratik boya hesabı yöntemi:\n\n1. Alan Hesabı (M²)\nOdanızın taban alanını duvar alanıyla karıştırmayın. Ortalama tavan yüksekliğine (2.60m) sahip 20 m²'lik bir salonun yaklaşık 45-50 m² duvar alanı vardır. (Kapı ve pencereler düşüldükten sonra).\n\n2. 1 Kova Boya Ne Kadar Yer Yapar?\nStandart iç cephe silikonlu su bazlı boyalar genellikle 15 Litre (yaklaşık 20 kg) tenekelerde satılır. Ortalama bir yüzeyde (çok pürüzlü veya çok koyu renkli olmayan), 15 litrelik bir kova boya, ÇİFT KAT uygulamada yaklaşık 90 ila 100 m² duvar yüzeyini boyayabilir.\n\nBu hesaba göre; 15 litrelik tek bir kova boya ile ortalama büyüklükte (20-25 m² taban alanlı) 2 adet odayı rahatlıkla boyayabilirsiniz. Eğer tüm evi (örneğin 3+1, 120 m² bir ev) boyayacaksanız, genellikle 2 adet 15 litrelik kova boya (toplam 30 litre) yeterli olacaktır.\n\nİpucu: Koyu bir renkten açık bir renge dönüş yapıyorsanız, boyanın kapatıcılığı düşeceği için 3. katı vurmanız gerekebilir. Bu durumda boya sarfiyatınız %50 oranında artacaktır.","image":"assets/blog_boya.jpg","date":"18 Ekim 2026","tags":"boya, badana, sarfiyat, hesaplama"},{"id":"7","title":"Anahtar Teslim İnşaat Modeli Nedir?","category":"İNŞAAT","excerpt":"Arsanız var ve ev yaptırmak istiyorsunuz. Anahtar teslim modelinin avantajları.","content":"Arsanız var ve üzerine hayalinizdeki evi veya ticari yapıyı inşa ettirmek istiyorsunuz. Karşınıza çıkacak en yaygın ve risksiz yöntemlerden biri 'Anahtar Teslim' (Turn-key) inşaat modelidir.\n\nAnahtar Teslim Nedir?\nAdından da anlaşılacağı gibi, inşaatın temel kazısından başlayıp; çatısı, boyası, parkesi, mutfak dolapları ve hatta çevre düzenlemesine kadar tüm işlemlerinin tek bir yüklenici firma (müteahhit) tarafından yapılmasıdır. İnşaat bittiğinde mal sahibi sadece 'anahtarı alıp' kapıyı açar ve içeri girer.\n\nAvantajları Nelerdir?\n1. Tek Muhatap: Elektrikçiyle, demirciyle, boyacıyla ayrı ayrı uğraşmazsınız. Yaşanacak her sorunda karşınızda sorumlu tek bir firma (Örneğin: PROKONT) vardır.\n2. Sabit Bütçe: İşe başlamadan önce sözleşmede belirlenen fiyat geçerlidir. Malzeme fiyatlarındaki dalgalanmalar veya ustaların sonradan fiyat artırması sizi etkilemez. Bütçenizi önceden tam olarak bilirsiniz.\n3. Zaman Tasarrufu: İş programı yüklenici firma tarafından profesyonelce yönetilir. Ekipler birbirini beklemez, inşaat belirlenen sürede hızla biter.\n\nDezavantajı Var mı?\nTaşeronları kendiniz organize ettiğiniz sisteme göre görünürde bir miktar daha maliyetli olabilir. Ancak stres, zaman kaybı ve malzeme fireleri (yanlış kesimler, çalan ustalar vs.) hesaba katıldığında Anahtar Teslim her zaman en kârlı ve huzurlu yoldur.","image":"assets/blog_insaat.jpg","date":"20 Ekim 2026","tags":"insaat, anahtar teslim, proje, muteahhit"},{"id":"8","title":"Kış gelmeden çatı izolasyonu yaptırmanın 5 avantajı.","category":"YALITIM","excerpt":"Çatı izolasyonunu son ana bırakmamak için bilmeniz gerekenler.","content":"Çatı izolasyonu genellikle binaların su akıtmaya başladığı, yağmurlu ve soğuk kış aylarında akla gelir. Ancak bu işlemi yaz veya sonbahar aylarında yaptırmanın sayısız avantajı vardır.\n\n1. Daha Verimli Uygulama\nSu yalıtım malzemelerinin (membran, sürme esaslı yalıtımlar vb.) zemine tam olarak tutunabilmesi için yüzeyin tamamen kuru olması gerekir. Kışın nemli veya ıslak zemine yapılan izolasyon kısa sürede atar ve bozulur.\n\n2. Usta ve Firma Bulma Kolaylığı\nKış aylarında yağmurlar başladığında çatı ustaları inanılmaz derecede yoğun olur. Yaz aylarında ise hem daha rahat usta bulabilir hem de pazarlık şansınızı artırabilirsiniz.\n\n3. Hızlı Kuruma\nUygulanan kimyasal yalıtım malzemeleri sıcak havalarda çok daha hızlı kürlenir (kurur). Bu sayede işlemler daha çabuk biter ve çatı bir sonraki kışa tam anlamıyla hazır hale gelir.\n\n4. Daha Uygun Fiyatlar\nKış aylarında artan acil talepler, hem malzeme hem de işçilik fiyatlarını yukarı çeker. İşi ölü sezonda yaptırmak bütçenize dost bir yaklaşımdır.\n\n5. Enerji Tasarrufuna Erken Başlayın\nÇatı izolasyonu sadece suyu değil, ısıyı da yalıtır. Kışın içerideki sıcak havanın çatıdan kaçmasını engelleyerek doğalgaz faturanızda %20-25'e varan tasarruf sağlar. Kışa girmeden yalıtımı bitirirseniz, tasarruf etmeye ilk günden başlarsınız.","image":"assets/blog_cati.jpg","date":"22 Ekim 2026","tags":"cati, yalitim, izolasyon, kis"},{"id":"9","title":"Mutfak tadilatı yaparken yapılan en büyük 5 hata.","category":"TADİLAT","excerpt":"Göz alıcı bir mutfak yaparken işlevselliği nasıl kaybediyoruz?","content":"Mutfak tadilatı evin en maliyetli ve en çok özen gösterilen kısımlarından biridir. Ancak sadece görüntüye odaklanmak ileride büyük kullanım zorlukları yaratabilir.\n\n1. Çalışma Üçgenini Bozmak\nBuzdolabı, evye ve ocak arasındaki hayali üçgene 'çalışma üçgeni' denir. Bu üçlünün birbirine çok uzak veya çok yakın olması mutfakta çalışmayı eziyete dönüştürür.\n\n2. Yetersiz Aydınlatma\nTezgah üstünü sadece tavandaki tek bir avize ile aydınlatmaya çalışmak, kendi gölgenizin tezgahınıza düşmesine neden olur. Dolap altı LED şeritler hayat kurtarır.\n\n3. Çekmece Yerine Kapaklı Alt Dolap Kullanmak\nAlt dolaplarda kapak kullanmak, tencere ararken iki büklüm olmanıza sebep olur. Bunun yerine derin ve geniş çekmeceler (raylı sistemler) tercih edin.\n\n4. Elektrik Prizlerini Unutmak\nKahve makinesi, blender, tost makinesi... Tezgah üstü prizlerin sayısını baştan fazla tutmazsanız, mutfağınız kısa sürede uzatma kablosu çöplüğüne döner.\n\n5. Ucuz Donanım Kullanmak\nMDF dolap gövdeleri ne kadar sağlam olursa olsun, eğer ucuz menteşe ve ray kullanırsanız birkaç ay içinde dolap kapaklarınız sarkar ve çekmeceleriniz bozulur.","image":"assets/blog_mutfak.jpg","date":"24 Ekim 2026","tags":"mutfak, tadilat, dekorasyon, hata"},{"id":"10","title":"Asma tavan sistemleri: Alçıpan mı, taş yünü mü?","category":"DEKORASYON","excerpt":"Mekanınız için doğru asma tavan çözümünü seçin.","content":"Tesisatları gizlemek, aydınlatma armatürlerini yerleştirmek veya sadece estetik bir görünüm katmak için asma tavanlar vazgeçilmezdir. Peki hangi sistemi seçmelisiniz?\n\nAlçıpan Asma Tavan\nEvlerde, ofislerde ve lüks mekanlarda en çok tercih edilen sistemdir.\n- Avantajları: İstenilen her şekle (kavisli, göbekli vb.) girebilir. Gizli ışık (led) bantları için mükemmeldir. Ek yeri belli olmaz, yekpare bir görüntü sunar.\n- Dezavantajları: Yukarıdaki tesisata müdahale etmek zordur, müdahale kapağı bırakmak gerekir. Suya karşı (yeşil alçıpan hariç) hassastır.\n\nTaş Yünü (Karolam) Asma Tavan\nGenellikle hastaneler, ofisler, okullar ve ticari alanlarda kullanılan 60x60 cm kare petek sistemlerdir.\n- Avantajları: Tesisata müdahale etmek çok kolaydır; sadece bir plakayı havaya kaldırmanız yeterlidir. Mükemmel ses yalıtımı (akustik) sağlar. Uygulaması çok hızlıdır, boya gerektirmez.\n- Dezavantajları: Estetik olarak ev kullanımına çok uygun değildir, daha endüstriyel/ofis bir görünümü vardır.\n\nKararınızı verirken; eğer evinizde şık ve özel bir tasarım istiyorsanız Alçıpan, eğer sürekli müdahale edilmesi gereken bir havalandırma sisteminiz varsa Taş Yünü tercih etmelisiniz.","image":"assets/blog_asmatavan.jpg","date":"26 Ekim 2026","tags":"asma tavan, alcipan, tasyunu, dekorasyon"},{"id":"11","title":"Dış cephe boyası alırken nelere dikkat edilmeli?","category":"BOYA","excerpt":"Binanızı dış etkenlerden koruyacak doğru boya seçimi.","content":"Dış cephe boyası sadece binanızı güzelleştirmekle kalmaz, aynı zamanda yağmur, güneş (UV) ve don gibi aşındırıcı etkilere karşı binanızın zırhı görevini görür.\n\nİşte boya seçerken dikkat etmeniz gerekenler:\n\n1. Silikon Katkısı\nDış cephe boyalarında silikon olmazsa olmazdır. Silikon, su itici bir özellik kazandırır (yağmur suyunu kaydırır) ancak aynı zamanda binanın nefes almasına izin verir.\n\n2. UV Dayanımı ve Renk Solması\nÖzellikle koyu renkler güneş ışınlarını daha çok çeker ve solma eğilimindedir. Kaliteli bir dış cephe boyasında yüksek UV dayanımı olmalıdır. Eğer binanız çok güneş alıyorsa, açık ve pastel tonları tercih etmek daha akıllıca olacaktır.\n\n3. Esneklik (Elastomerik Boyalar)\nBinalar sıcaklık farklarından dolayı mikro düzeyde genleşir ve büzülür. Eğer boya yeterince esnek değilse, kılcal çatlaklar oluşur. Elastomerik (esnek) boyalar %300'e kadar esneyerek bu çatlakları köprüler.\n\n4. Kendi Kendini Temizleme (Fotokatalitik)\nBazı üst düzey dış cephe boyaları, güneş ışığı ve yağmurun etkisiyle yüzeydeki kiri çözer ve kendi kendini temizler. Tozlu bir bölgede veya ana cadde üzerinde oturuyorsanız bu özellik hayat kurtarır.","image":"assets/blog_discephe.jpg","date":"28 Ekim 2026","tags":"boya, dis cephe, silikonlu, elastik"},{"id":"12","title":"Eski fayansın üstüne yeni fayans yapılır mı?","category":"SERAMİK","excerpt":"Kırım döküm yapmadan fayans yenilemenin püf noktaları.","content":"Banyosunu veya mutfağını yenilemek isteyenlerin en çok sorduğu sorulardan biri: 'Eski fayansları kırmadan üzerine yenisini yapıştırabilir miyiz?' Kısa cevap: Evet, yapılabilir. Ancak belirli şartlara uymak kaydıyla.\n\nKırım Yapmamanın Avantajları\nEn büyük avantajı moloz çıkmamasıdır. Toz, gürültü ve hafriyat atım masraflarından kurtulursunuz. Süreç çok daha hızlı ilerler.\n\nDikkat Edilmesi Gereken Kritik Noktalar:\n1. Zemin Sağlamlığı\nEğer eski fayanslarınızın altı boşalmışsa, kabarmalar varsa veya duvardan ayrılmaya başlamışsa, ÜZERİNE YAPIŞTIRMA YAPILAMAZ. Eski zemin tamamen sağlam ve taşıyıcı olmalıdır.\n\n2. Astar Kullanımı Zorunludur\nFayansların yüzeyi sırlı ve parlaktır. Standart bir yapıştırıcı bu yüzeye tutunamaz. İşleme başlamadan 24 saat önce, yüzeye 'brüt beton astarı' veya 'seramik üzeri seramik astarı' (içinde kuvars kumu bulunan pürüzlü astarlar) sürülmelidir.\n\n3. Kot Farkı (Yükselme)\nFayans üstüne fayans yapıldığında zemin yaklaşık 1.5 - 2 cm yükselecektir. Bu durum, banyo kapınızın altına sürtmesine veya süzgeçlerin altta kalmasına neden olabilir. Kapı altlarının kesilmesi ve süzgeçlerin uzatma adaptörleri ile yükseltilmesi gerekir.\n\nÖzetle, eski seramikleriniz sağlamsa ve doğru astarlama yapılırsa 'fayans üstü fayans' uygulaması son derece güvenli ve ekonomik bir yöntemdir.","image":"assets/blog_fayansustu.jpg","date":"30 Ekim 2026","tags":"seramik, fayans, tadilat, pratik"},{"id":"13","title":"Metraj nedir? İnşaatta doğru miktar hesabı nasıl yapılır?","category":"İNŞAAT","excerpt":"Metrajın keşif, teklif ve malzeme siparişindeki rolünü adım adım öğrenin.","content":"Metraj, bir yapının veya tadilat projesinin kağıt üzerindeki projeden sahaya aktarılmasında gereken tüm uzunluk, alan, hacim ve adetlerin matematiksel olarak hesaplanmasıdır. Doğru metraj; malzeme israfını önler, bütçe sapmalarını engeller ve taşeronlarla şeffaf çalışmanın temelini oluşturur.\n\n1. Metraj Türleri Nelerdir?\n- Keşif (Ön) Metrajı: Proje başında yaklaşık maliyeti belirlemek ve bütçe planlamak için yapılır.\n- Uygulama Metrajı: Şantiyede siparişlerin verilmesi ve günlük iş programının hazırlanması için kullanılır.\n- Kesin Hesap (Hakediş) Metrajı: İmalat bittikten sonra yerinde yapılan nihai ölçümlerdir.\n\n2. Metraj Cetveli ve Standart Birimler\nİnşaatta her kalemin standart bir ölçü birimi vardır:\n- Kazı, beton, hafriyat: Metreküp (m³)\n- Sıva, boya, seramik, şap, kalıp, yalıtım: Metrekare (m²)\n- Demir, çelik, profil: Kilogram veya Ton (kg / ton)\n- Süpürgelik, boru, kablo, bordür: Metretül (mt)\n- Kapı, pencere, armatür, anahtar-priz: Adet\n\n3. Minha (Boşluk Düşme) Kuralları\nMetraj yaparken en sık yapılan hata duvar boşluklarının unutulmasıdır. Duvar veya sıva metrajı çıkarılırken kapı ve pencere boşlukları toplam alandan mutlaka düşülmelidir (minha edilmelidir). Ancak Çevre ve Şehircilik Bakanlığı poz tanımlarına göre küçük boşluklar (örneğin 1 m²'den küçük delikler) işçilik zorluğu sebebiyle düşülmeyebilir.\n\n4. Fire Oranlarının Hesaba Katılması\nHiçbir malzeme sıfır kayıpla uygulanamaz. Köşe kesimleri, kırılmalar ve nakliye zayiatı için seramikte %7-10, parkede %5-7, demirde %3-5 fire payı eklenmelidir.\n\nPROKONT Akıllı Planlayıcı üzerinden projenizin metrajlarını girdiğinizde, resmi 2026 birim fiyatlarıyla otomatik keşif özeti çıkarabilir ve sürpriz maliyetleri sıfıra indirebilirsiniz.","image":"assets/blog_metraj_kesif.jpg","date":"01 Kasım 2026","tags":"metraj, kesif, insaat, maliyet"},{"id":"14","title":"Yaklaşık maliyet hesabında hangi kalemler unutulmamalı?","category":"İNŞAAT","excerpt":"Sadece malzeme fiyatına bakmadan gerçekçi yaklaşık maliyet hazırlamanın yolları.","content":"Yaklaşık maliyet hesabı, bir inşaat veya tadilat projesine başlamadan önce harcanacak toplam paranın önceden tespit edilmesidir. Çoğu zaman sadece seramik, boya ve parke gibi ana kalemler hesaplanır; fakat 'gizli maliyetler' yüzünden bütçeler %30 ila %50 oranında aşılır.\n\n1. Nakliye, Hamaliye ve Katlara Taşıma Giderleri\nMalzemeyi mağazadan satın almak işin sadece ilk adımıdır. Şantiyeye nakliyesi, özellikle asansörsüz veya yüksek katlı binalarda katlara taşınması ciddi bir işçilik kalemidir. 1 palet seramik yaklaşık 1.2 ton çeker ve kata çıkarma maliyeti göz ardı edilmemelidir.\n\n2. Yıkım, Kırım ve Moloz Tahliye Harçları\nEski banyonun kırılması, mutfak duvarının yıkılması sonrası ortaya onlarca çuval moloz çıkar. Molozun çuvallanması, apartmandan indirilmesi, moloz kamyonu ve belediyenin lisanslı döküm sahası harçları önemli bir masraftır.\n\n3. Sarf Malzemeleri ve Yardımcı İmalatlar\nVidalar, dübeller, koruma naylonları, kağıt bantlar, derz artıları, yapıştırıcı astarları ve silikonlar... Genellikle keşif listesine yazılmayan bu yardımcı malzemeler toplamda ciddi meblağlara ulaşır.\n\n4. Şantiye Güvenliği ve Temizlik Masrafları\nİş bittikten sonraki kaba ve ince şantiye temizliği, koruyucu zemin örtüleri ve şantiye elektrik/su abonelik bedelleri unutulmamalıdır.\n\n5. %10-15 Beklenmedik Gider (Risk Fonu)\nDuvar kırıldığında çürümüş tesisat borularının çıkması veya zeminde şap hatalarının belirmesi gibi sürprizler için toplam bütçenizin en az %15'ini kenarda tutmalısınız.","image":"assets/blog-covers/kesif-maliyet.png","date":"03 Kasım 2026","tags":"yaklasik maliyet, kesif, teklif, insaat"},{"id":"15","title":"Beton sınıfı seçilirken nelere dikkat edilmeli?","category":"İNŞAAT","excerpt":"C25/30, C30/37 ve daha yüksek sınıfların kullanım amacı proje kararına bağlıdır.","content":"Beton, modern yapıların omurgasıdır. Bir yapının deprem güvenliği, dayanıklılığı ve taşıma kapasitesi doğrudan doğruya seçilen beton sınıfına ve yerleştirme kalitesine bağlıdır.\n\n1. Beton Sınıfları Ne Anlama Gelir?\nC20, C25, C30, C35 gibi sınıflardaki 'C' harfi Concrete (Beton), yanındaki rakam ise standart silindir numunenin 28 günlük basınç dayanımını (MPa cinsinden) ifade eder. Örneğin C30 betonu, 1 santimetrekaresinde yaklaşık 300 kg yük taşıma kapasitesine sahiptir.\n\n2. Türkiye Bina Deprem Yönetmeliği Şartları\nGüncel deprem yönetmeliğimize göre yeni yapılacak binalarda taşıyıcı sistem için ASGARİ beton sınıfı C25/30'dur. Deprem riski yüksek bölgelerde ve nitelikli konut projelerinde C30 ve C35 beton sınıfları standart hale gelmiştir.\n\n3. Şantiyede Yapılan En Büyük Hata: 'Su Katmak'\nTransmikser şantiyeye geldiğinde betonun kıvamı koyu görünebilir. Pompa operatörlerinin veya beton işçilerinin betonu daha kolay yaymak için miksere fazladan su eklemesi betonun mukavemetini %40'a varan oranda öldürür. Betona asla harici su katılmamalı, akışkanlık gerekiyorsa süper akışkanlaştırıcı kimyasal katkılar kullanılmalıdır.\n\n4. Kürleme (Sulama) ve Bakımın Önemi\nBeton döküldükten sonra hidratasyon ısısı üretir. İlk 7 gün boyunca sabah ve akşam düzenli sulanmalı, sıcak havalarda buharlaşmayı önlemek için kür katkısı veya ıslak çuvallarla örtülmelidir. Bakımı yapılmayan C35 beton, sulanmış C25 betondan daha zayıf kalabilir.","image":"assets/blog_beton_dokumu.jpg","date":"05 Kasım 2026","tags":"beton, betonarme, c2530, santiye"},{"id":"16","title":"Şap çatlamasını önlemek için 6 temel uygulama kuralı","category":"ZEMİN","excerpt":"Zemin hazırlığı, derz ve kuruma süresi şap performansını belirler.","content":"Zemin kaplamaları (laminat parke, seramik, mermer) ne kadar kaliteli olursa olsun, altındaki şap düzgün değilse çatlamalar, kabarmalar ve gıcırtılar kaçınılmazdır. Şapın çatlamasını önlemek için şu 6 kurala mutlaka uyun:\n\n1. Su-Çimento Oranını Düşük Tutun\nŞap harcını çamur gibi sulu hazırlamak ustaların işini kolaylaştırır ama kururken suyun buharlaşmasıyla harç büzüşür ve derin 'rötre çatlakları' oluşturur. Şap harcı nemli toprak kıvamında (yarı kuru şap) olmalıdır.\n\n2. Polipropilen Elyaf Katkısı Kullanın\nŞap harcına katılan sentetik elyaf lifleri, harcın içinde milyonlarca mikro köprü kurarak mikro düzeydeki gerilmeleri karşılar ve çatlamayı %80 oranında engeller.\n\n3. Çevre Bandı (Fuga) ile Duvarlardan Ayırın\nŞap dökülmeden önce tüm duvar diplerine 5-8 mm kalınlığında polietilen şilte şeritleri çekilmelidir. Şapın duvarlara yapışması engellenmeli, zemin yüzer halde çalışmalıdır.\n\n4. Genleşme Derzlerini (Derz Kesimi) Unutmayın\nGeniş alanlarda (25 m²'yi aşan odalar veya kapı eşikleri) şap döküldükten sonraki gün derz kesme makinesiyle kalınlığın üçte biri kadar genleşme derzleri açılmalıdır.\n\n5. Minimum Kalınlık Sınırına Dikkat Edin\nYalıtım şiltesi veya strafor üzerine yapılan yüzer şaplarda kalınlık en az 4-5 cm olmalıdır. 3 cm'nin altındaki şaplar üzerine basıldığında kırılır.\n\n6. Hızlı Kurumaya Karşı Koruyun ve Sulayın\nŞap döküldükten sonra kapı ve pencereler kapalı tutularak ceryan yapması engellenmelidir. İlk 3 gün hafifçe nemlendirilerek çatlaması önlenmelidir.","image":"assets/blog_sap_uygulamasi.jpg","date":"07 Kasım 2026","tags":"sap, zemin, seramik, parke"},{"id":"17","title":"Mantolamada doğru kalınlık nasıl belirlenir?","category":"YALITIM","excerpt":"Yalıtım levhası kalınlığı iklim, duvar yapısı ve proje hesabına göre seçilmelidir.","content":"Dış cephe mantolamasında yapılan en büyük tasarruf yanılgısı, levha kalınlığını ince seçmektir. Birçok bina sakini 4 cm mi 5 cm mi ikilemine düşerken, gelişmiş ülkelerde 10-15 cm standart olarak uygulanmaktadır.\n\n1. Isı Bölgesi Standartları (TS 825)\nTürkiye 4 farklı iklim bölgesine ayrılmıştır. 1. Bölge (Antalya, İzmir) ile 3. ve 4. Bölgeler (Kayseri, Ankara, Erzurum) aynı kalınlıkta yalıtılamaz. İç Anadolu ve Doğu Anadolu gibi soğuk kış şartlarının hüküm sürdüğü yerlerde asgari 6-8 cm levha kalınlığı tercih edilmelidir.\n\n2. Maliyet Dağılımı ve Kalınlık İlişkisi\nMantolama bütçesinde yalıtım levhası toplam maliyetin sadece %25-30'unu oluşturur. İskele kurulumu, yapıştırıcı, sıva, file, dekoratif kaplama, dış cephe boyası ve işçilik giderleri kalınlıktan bağımsız olarak sabittir. 5 cm yerine 8 cm levha seçtiğinizde toplam maliyet sadece %10-15 artar; ancak elde edeceğiniz kışlık yakıt tasarrufu %30 daha fazla olur.\n\n3. Karbonlu EPS vs Beyaz EPS Kalınlık Farkı\nKarbon takviyeli grafitli EPS levhalar, ısı iletkenlik değeri (λ = 0.031 - 0.032 W/mK) açısından beyaz EPS'ye göre daha üstündür. 6 cm karbonlu EPS, yaklaşık 8 cm standart beyaz EPS ile eşdeğer performans sunar.\n\n4. Cephe Detayları ve Pencereler\nKalın levha seçildiğinde pencere denizliklerinin (damlalık) uzatılması ve pencere merkezlerinin de en az 2-3 cm ince levhalarla yalıtılması ısı köprülerini engellemek için zorunludur.","image":"assets/blog_17_mantolama_kalinlik.jpg","date":"09 Kasım 2026","tags":"mantolama, eps, yalıtım, enerji"},{"id":"18","title":"Mantolama sonrası cephede çatlak neden oluşur?","category":"YALITIM","excerpt":"File uygulaması, kuruma süresi ve detay çözümleri cephe çatlaklarında kritik rol oynar.","content":"Mantolama yaptırdıktan 1-2 yıl sonra cephede örümcek ağı şeklinde çatlaklar, kabarmalar veya dökülmeler görmek büyük bir hayal kırıklığıdır. Bu çatlakların başlıca sebepleri şunlardır:\n\n1. Sıva Donatı Filesinin Yanlış Konumlandırılması\nEn yaygın usta hatası; fileyi kuru straforun üzerine serip üzerinden sıva çekmektir. Bu durumda file strafora yapışır ve görev yapamaz. Doğru yöntem; önce 1. kat sıvanın çekilmesi, file henüz yaş olan sıvanın içerisine gömülmesi ve ardından 2. kat sıvanın vurulmasıdır.\n\n2. File Bindirme Paylarının Yetersiz Olması\nYan yana gelen donatı fileleri ek yerlerinde en az 10 cm birbiri üzerine bindirilmelidir. Bindirme yapılmadan yan yana getirilen yerler ilk kış ayında çizgi şeklinde çatlar.\n\n3. Pencere Köşelerindeki Çapraz Takviye Filesinin Atlanması\nPencerelerin 4 köşesi gerilmenin en yoğun olduğu yerlerdir. Bu köşelere 45 derece açıyla en az 30x40 cm boyutunda çapraz takviye fileleri yerleştirilmezse, köşelerden çapraz çatlaklar fırlar.\n\n4. Hatalı Dübelleme ve Isı Köprüleri\nDübeller levhanın yüzeyiyle tam hemyüz olmalıdır. Çekiçle çok sert çakılıp levhayı ezen dübeller sonradan çukurlaşır ve sıva çatlağına sebep olur.\n\n5. Aşırı Sıcakta Sıva Yapılması\nGüneşin kavurduğu cephede sıva harcı suyunu aniden kaybederse plastik büzülme çatlakları oluşur. Çalışma gölge cephelerde yürütülmelidir.","image":"assets/blog_18_cephe_catlak.jpg","date":"11 Kasım 2026","tags":"mantolama, cephe, çatlak, yalıtım"},{"id":"19","title":"Seramik derz rengi ve genişliği nasıl seçilir?","category":"SERAMİK","excerpt":"Doğru derz seçimi hem görünümü hem de kaplamanın uzun ömürlü olmasını sağlar.","content":"Fayans ve seramik uygulamalarında görsel sonucu belirleyen en kritik son dokunuş derz dolgusudur. Yanlış derz rengi en pahalı seramiği bile basit gösterirken, doğru seçim mekana lüks bir hava katar.\n\n1. Rektifiye (Lazer Kesim) Seramiklerde Derz Genişliği\nKenarları 90 derece dik kesilmiş rektifiye seramiklerde sıfır derz yapılmamalıdır. Isı farklarından dolayı seramiklerin genleşebilmesi için en az 1 mm ila 1.5 mm derz payı bırakılmalıdır. Standart pahlı seramiklerde ise 2 mm - 3 mm idealdir.\n\n2. Ton-sür-Ton (Bütüncül) Renk Seçimi\nMekanın daha geniş, ferah ve kesintisiz görünmesini istiyorsanız seramik rengine en yakın derz dolgusunu seçmelisiniz. Özellikle mermer desenli açık renk seramiklerde beyaz, bej veya açık gri derzler mükemmel bir akış sağlar.\n\n3. Kontrast (Grafik) Etki\nBeyaz metro seramikler (subway tiles) arasına antrasit veya siyah derz uygulamak vintage ve loft tarzı mekanlarda çok popülerdir. Ancak koyu derz uygulamasında ustalık çok hassas olmalıdır; en ufak çizgi kayması hemen göze batar.\n\n4. Islak Hacimlerde Epoksi Derz Çözümü\nBanyo, duş içi ve mutfak tezgah aralarında çimento esaslı standart derzler zamanla su emerek kararır ve küflenir. Epoksi esaslı derz dolgular su geçirmez, leke tutmaz ve kimyasallara dayanıklıdır; yıllarca ilk günkü rengini korur.","image":"assets/blog_derz_dolgu.jpg","date":"13 Kasım 2026","tags":"seramik, derz, banyo, kaplama"},{"id":"20","title":"Banyoda havalandırma neden su yalıtımı kadar önemlidir?","category":"TADİLAT","excerpt":"Nem, küf ve kabaran boyayı azaltmak için banyoda doğru hava akışı gerekir.","content":"Banyo tadilatlarında su yalıtımına büyük paralar harcanırken havalandırma çoğu zaman unutulur. Oysa yetersiz havalandırma, en iyi su yalıtımını bile birkaç yılda etkisiz hale getirebilir.\n\n1. Buharın Duvarlara ve Mobilyalara Zararı\nSıcak bir duş alındığında banyodaki bağıl nem oranı %90'ın üzerine çıkar. Dışarı tahliye edilemeyen su buharı soğuk yüzeylere (fayans, ayna, tavan) çarparak yoğuşur. Bu durum banyo dolaplarının kabarmasına, kapıların şişmesine ve tavan boyasının pul pul dökülmesine yol açar.\n\n2. Küf ve Siyah Bakteri Oluşumu\nSürekli nemli kalan ortamlarda silikon kenarlarında ve derz dolgu aralarında siyah küf mantarları ürer. Bu mantarlar sadece kötü görüntüye sebep olmakla kalmaz, solunum yolu hastalıklarına ve alerjilere zemin hazırlar.\n\n3. Mekanik Havalandırma Fanı (Aspiratör) Seçimi\nPenceresiz banyolarda standart menfezler yeterli çekişi sağlayamaz. Geri tepme ventilli (binanın baca kokusunu içeri almayan), zaman ayarlı (banyodan çıktıktan sonra 5-10 dakika daha çalışan) ve sessiz çalışan bir elektrikli aspiratör takılmalıdır.\n\n4. Kapı Altı Hava Boşluğu\nHavalandırma fanının verimli çekebilmesi için banyoya taze hava girmesi gerekir. Banyo kapısının altında en az 1.5 - 2 cm hava boşluğu veya kapı altı havalandırma ızgarası bırakılmalıdır.","image":"assets/blog_banyo_havalandirma.jpg","date":"15 Kasım 2026","tags":"banyo, havalandirma, nem, tadilat"},{"id":"21","title":"Ev tadilatında bütçe payı nasıl dağıtılmalı?","category":"TADİLAT","excerpt":"Beklenmeyen işler için ayrılan pay, tadilatın yarım kalmasını önler.","content":"Tadilat bütçesini doğru planlamak, işin ortasında parasız kalıp inşaatı yarım bırakma riskini ortadan kaldırır. Profesyonel mimarlar ve şantiye şefleri bütçeyi şu altın oranlarla yönetir:\n\n1. Altyapı ve Tesisat Payı (%25 - %30)\nGörünmeyen ama evin kalbi olan kısım burasıdır. Elektrik panosu ve kablolama, temiz ve pis su boruları, kalorifer/doğalgaz tesisatı, kırım ve moloz işleri bu bütçeden karşılanır. Altyapıdan kısarak fayansa para yatırmak büyük bir hatadır.\n\n2. Islak Hacimler ve Sabit Mobilya (%35 - %40)\nBütçenin en büyük dilimini mutfak ve banyo oluşturur. Mutfak dolapları, tezgah, seramikler, duşakabin, banyo dolabı, klozet ve bataryalar bu kategoriye girer.\n\n3. Yüzey Kaplamaları ve İnce İşler (%15 - %20)\nLaminat parkeler, süpürgelikler, iç kapılar, alçı boya badana ve tavan aydınlatmaları evin kozmetik yüzüdür.\n\n4. Görünmez Giderler ve Nakliye (%5)\nNakliye, katlara taşıma, hırdavat sarfiyatı ve kaba temizlik giderleri.\n\n5. Risk ve Beklenmedik Masraf Fonu (%10 - %15)\nÖngörülemeyen arızalar ve sonradan beğeneceğiniz malzeme farkları için kesinlikle kenarda bekletilmesi gereken güvence payıdır.","image":"assets/blog_21_tadilat_butce.jpg","date":"17 Kasım 2026","tags":"tadilat, bütçe, teklif, planlama"},{"id":"22","title":"Mutfak tezgahı seçerken kullanım alışkanlığı neden önemlidir?","category":"DEKORASYON","excerpt":"Granit, kuvars ve kompakt yüzeyleri yalnızca görünüşe göre değerlendirmeyin.","content":"Mutfak tezgahı seçerken sadece rengine ve katalogdaki duruşuna bakmak büyük bir hatadır. Yemek pişirme sıklığınız, tezgah üstüne sıcak tencere koyma alışkanlığınız ve temizlik rutininiz en doğru malzemeyi belirler.\n\n1. Porselen Tezgahlar: Zirve Dayanıklılık\nSon yılların en popüler malzemesi olan porselen tezgahlar; fırından çıkan kızgın tepsiden, doğrudan üzerinde bıçakla et kesilmesinden veya dökülen limon ve sirkeden kesinlikle etkilenmez. Sıfır gözenekli yapısıyla leke tutmaz. Tek dezavantajı montajının ve malzeme fiyatının yüksek olmasıdır.\n\n2. Kuvars Tezgahlar (Çimstone / Belenco)\n%90'ın üzerinde doğal kuvars minerali ile reçinenin preslenmesiyle üretilir. Çizilmeye ve lekelere karşı çok dayanıklıdır, zengin renk seçenekleri vardır. Ancak içerisindeki reçine nedeniyle doğrudan sıcak tencere konulması durumunda termal şokla yanık izi oluşabilir; nihale kullanılmalıdır.\n\n3. Granit Tezgahlar: Doğal ve Ağırbaşlı\n%100 doğal taştır. Sıcağa karşı mükemmel dayanıklıdır. Ancak doğal gözeneklere sahip olduğu için yılda bir kez yüzey koruyucu cila ile emprenye edilmesi gerekir; aksi takdirde yağ lekelerini emebilir.\n\n4. Laminat ve Masif Ahşap Tezgahlar\nLaminat son derece ekonomiktir ancak ek yerlerinden su alırsa şişer. Masif ahşap ise çok sıcaktır ancak düzenli yağlama ve aşırı özenli kullanım ister.","image":"assets/blog_22_mutfak_tezgah.jpg","date":"19 Kasım 2026","tags":"mutfak, tezgah, dekorasyon, tadilat"},{"id":"23","title":"Laminat parke su görünce neden kabarır?","category":"ZEMİN","excerpt":"Nem bariyeri, derz boşluğu ve doğru ürün sınıfı parke ömrünü uzatır.","content":"Laminat parke, evlerde en çok tercih edilen zemin kaplaması olsa da suya maruz kaldığında hızlıca şişip deforme olmasıyla bilinir. Parkenin su karşısındaki davranışını anlamak ve doğru müdahale etmek zemini kurtarabilir.\n\n1. Laminat Parkenin Anatomisi\nLaminat parkenin taşıyıcı gövdesi HDF (High Density Fiberboard), yani yüksek yoğunlukta preslenmiş ahşap liflerinden oluşur. Ahşap lifleri doğası gereği higroskopiktir (nemi çeker). Su, parke ek yerlerinden (kilitlerden) içeri sızdığında HDF sünger gibi suyu emer ve genleşir.\n\n2. Ek Yerlerindeki Şişme Neden Kalıcı Olur?\nSu emen ahşap lifleri şiştiğinde üstteki melamin koruyucu katmanı yukarı doğru iter. Kuruduktan sonra bile lifler eski orijinal preslenmiş formuna dönemez ve ek yerleri kabarık, sivri bir halde kalır.\n\n3. Su Temasında İlk 15 Dakika Kuralı\nYere su döküldüğünde hemen kuru bir bezle emdirilmeli, paspas sonrası zemin ıslak bırakılmamalıdır. Büyük su baskınlarında ise süpürgelikler hemen sökülmeli, parkelerin altındaki şiltenin hava alması sağlanmalıdır.\n\n4. Suya Dayanıklı (AquaStop) Parkeler Çözüm mü?\nYeni nesil hidrofobik reçineli HDF paneller ve kilitlerine parafin/balmumu çekilmiş suya dayanıklı parkeler, 24 ila 72 saate kadar yüzeydeki suya direnç gösterir. Mutfak ve koridor gibi ıslak hacim yakınlarında bu modeller tercih edilmelidir.","image":"assets/blog_parke_kabarma.jpg","date":"21 Kasım 2026","tags":"laminat, parke, zemin, nem"},{"id":"24","title":"Parke altı şilte seçimi ses konforunu nasıl etkiler?","category":"ZEMİN","excerpt":"Şilte, zemindeki küçük toleransları karşılar ve darbe sesini azaltmaya yardımcı olur.","content":"Laminat parke döşenirken çoğu zaman sadece parkenin markasına ve sınıfına odaklanılır; altındaki şilte ise ustanın getirdiği standart beyaz köpükle geçiştirilir. Oysa zeminin konforunu, ses yalıtımını ve ömrünü belirleyen gizli kahraman şiltedir.\n\n1. Yürüme Sesi (Oda İçi Ses) vs Darbe Sesi (Alt Kata Giden Ses)\n- Yansıma Sesi: Odanın içinde parke üzerinde topuklu ayakkabıyla veya sert tabanla yürürken çıkan yankılı 'tık-tık' sesidir.\n- Darbe Sesi: Zemindeki adım seslerinin ve titreşimlerin alt katın tavanına iletilmesidir. Doğru şilte alt kata giden sesi 18-22 dB azaltabilir.\n\n2. Şilte Türleri ve Performansları\n- Standart 2 mm Polietilen Şilte: Çok ucuzdur ancak zamanla ezilir, ses yalıtım kabiliyeti zayıftır.\n- Alüminyum Folyolu Kapalı Hücreli Şilte: Şapın nemini parkeye geçirmeyen buhar bariyeri sunar.\n- Mantarlı Şilte ve Ağır Kauçuk Şilteler: Ses yalıtımında en üst düzey performans sağlar, basıldığında tok ve sağlam bir his verir.\n- XPS (Karbonlu Oluklu) Parke Altı Levhaları: Zemindeki 1-2 mm'lik kılcal dalgalanmaları tolere eder ve ısı yalıtımı sağlar.\n\n3. Yerden Isıtmalı Evlerde Hayati Kural\nYerden ısıtmalı mekanlarda standart kalın şilte kullanırsanız ısıyı yukarı geçirmez, faturanız kabarır. Yerden ısıtmaya özel delikli ve düşük ısıl dirençli özel şilteler kullanılmalıdır.","image":"assets/blog_24_parke_silte.jpg","date":"23 Kasım 2026","tags":"parke, şilte, ses yalıtımı, zemin"},{"id":"25","title":"Boya rengini seçmeden önce ışığı test edin","category":"BOYA","excerpt":"Aynı renk gün ışığında ve yapay aydınlatmada farklı algılanabilir.","content":"Boya mağazasında küçücük bir kağıt kartelada beğenilen o mükemmel bej veya gri tonun, duvara sürüldüğünde bambaşka ve hayal kırıklığı yaratan bir renge dönüşmesi çok sık yaşanır. Bunun bir numaralı sebebi mekandaki ışıktır.\n\n1. Cephe Yönünün Renk Üzerindeki Etkisi\n- Kuzey Cephe Odalar: Gün boyunca soğuk ve hafif mavimsi bir doğal ışık alır. Soğuk gri veya buz mavisi tonlar bu odalarda kasvetli durur; sıcak alt tonlu kremler, sıcak bejler tercih edilmelidir.\n- Güney Cephe Odalar: Yoğun ve sıcak sarı gün ışığı alır. Bu odalarda sıcak renkler aşırı sararabilir; nötr ve hafif soğuk alt tonlu renkler dengeli durur.\n\n2. Yapay Aydınlatmanın (Kelvin Değeri) Rolü\n- 2700K - 3000K (Sıcak Sarı Işık): Renklerdeki sarı ve kırmızı pigmentleri öne çıkarır, grileri kahverengimsi gösterebilir.\n- 4000K (Doğal Gün Işığı): Rengin karteladaki gerçek tonunu en doğru yansıtan aydınlatmadır.\n- 6500K (Beyaz / Soğuk Işık): Renkleri soluklaştırır ve maviye çalar.\n\n3. Altın Kural: Büyük Numune Denemesi\nKarar vermeden önce beğendiğiniz renkten küçük bir deneme boyu (tester) alın. Rengi doğrudan duvara değil, büyük bir beyaz mukavvaya iki kat boyayın. Bu kartonu günün farklı saatlerinde odanın farklı duvarlarına koyup sabah, öğle ve gece ışığında nasıl durduğunu inceleyin.","image":"assets/blog_25_boya_isik.jpg","date":"25 Kasım 2026","tags":"boya, renk seçimi, dekorasyon, badana"},{"id":"26","title":"Dış cephe boyasında astar neden atlanmamalı?","category":"BOYA","excerpt":"Doğru astar, yüzey emiciliğini dengeler ve boya tüketimini kontrol eder.","content":"Dış cephe boyama işlerinde ustaların 'zaman kazanmak' veya 'maliyeti düşürmek' amacıyla en çok atlamak istediği aşama astardır. Oysa dış cephede astar kullanmamak, boyanın ömrünü yarı yarıya azaltan en tehlikeli hatadır.\n\n1. Yüzey Emiciliğini Dengelemek\nSıvalı veya tamir görmüş dış cephe yüzeylerinde bazı bölgeler harcı fazla çekerken bazı bölgeler daha az çeker. Astarsız uygulanan boyada duvar boyayı dengesiz emer ve cephede dalgalanmalar, yama izleri ve ton farklılıkları oluşur.\n\n2. Boya Sarfiyatını %25-30 Düşürür\nPahalı dış cephe son kat boyasının doğrudan emici sıvaya çekilmesi boyanın boşa gitmesine neden olur. Astar, yüzeyin gözeneklerini doyurarak boyanın yüzeyde kalmasını sağlar ve malzeme tasarrufu sağlar.\n\n3. Mekanik ve Kimyasal Yapışma (Aderans)\nDış cephe astarı, yüzeydeki serbest toz parçacıklarını bağlar ve mikroskobik düzeyde pürüzlü bir köprü tabaka oluşturur. Boyanın kabarmasını, pul pul dökülmesini ve yağmur suyuyla ayrılmasını engeller.\n\n4. Hangi Astar Kullanılmalı?\nSilikonlu boya yapılacaksa mutlaka 'Silikonlu Dış Cephe Dönüşüm Astarı' kullanılmalıdır. Eski boyalı veya tebeşirlenmiş yüzeylerde ise şeffaf bağlayıcı astarlar tercih edilmelidir.","image":"assets/blog_26_discephe_astar.jpg","date":"27 Kasım 2026","tags":"dış cephe, boya, astar, cephe"},{"id":"27","title":"Asma tavanda aydınlatma planı ne zaman yapılmalı?","category":"DEKORASYON","excerpt":"Elektrik, havalandırma ve spot yerleşimini alçıpan kapanmadan netleştirin.","content":"Asma tavan projelerinde en sık yapılan koordinasyon hatası, tavan alçıpanla kapatıldıktan sonra elektrikçinin çağrılmasıdır. Bu durum sonradan alçıpanın delinmesine, taşıyıcı profillerin kesilmesine ve çirkin yama işlerine yol açar.\n\n1. Karkas Aşamasında Tesisatın Çekilmesi\nC ve U tavan profilleri tavana asıldıktan hemen sonra, alçıpan plakalar vidalanmadan önce tüm elektrik kablolaması tamamlanmalıdır. Kablolar koruyucu spiral borular içerisinden geçirilmeli ve tavan askı tellerine sabitlenmelidir.\n\n2. Taşıyıcı Profiller ile Spot Deliklerinin Çakışması\nSpot delikleri açılırken tavanın taşıyıcı sac profiline denk gelirse profil kesilmek zorunda kalır; bu da tavanın sarkmasına neden olur. Mimari aydınlatma planı önceden çizilmeli ve karkas aks aralıkları spot konumlarına göre şaşırtılmalıdır.\n\n3. Gizli Işık Bantlarında LED Trafolarının Saklanması\nAsma tavan gizli ışık havuzlarında en büyük sorun trafoların bozulduğunda değiştirilememesidir. LED şerit trafoları tavanın ulaşılamaz derinliklerine değil, gizli ışık havuzunun kenarına veya müdahale kapağına yakın yerlere konulmalıdır.\n\n4. Senaryolu Aydınlatma ve Dimmer Hatları\nTavan kapatılmadan önce ana aydınlatma, spotlar ve gizli LED bantları için ayrı anahtar linyeleri çekilmelidir. Tek anahtarla tüm ışıkların aynı anda yanması yerine esnek ışık senaryoları planlanmalıdır.","image":"assets/blog_27_tavan_aydinlatma.jpg","date":"29 Kasım 2026","tags":"asma tavan, aydınlatma, alçıpan, dekorasyon"},{"id":"28","title":"Yeşil alçıpan hangi alanlarda kullanılmalı?","category":"DEKORASYON","excerpt":"Neme dayanıklı levha doğru detayla uygulandığında ıslak hacimlerde avantaj sağlar.","content":"İnşaat ve tadilat sektöründe en çok tanınan levhalardan biri 'Yeşil Alçıpan'dır (Su ve Neme Dayanıklı Alçı Plaka). Ancak bu malzemenin nerede kullanılacağı ve sınırlarının ne olduğu çok iyi bilinmelidir.\n\n1. Yeşil Alçıpanın Standart Alçıpandan Farkı Nedir?\nStandart (beyaz) alçıpan neme maruz kaldığında bünyesine su çeker, yumuşar, sarkar ve üzerinde küf oluşur. Yeşil alçıpanın ise alçı çekirdeğine su itici kimyasallar ve silikon katkısı eklenmiştir. Karton yüzeyi özel mantar önleyici bileşenlerle kaplıdır.\n\n2. Zorunlu Kullanım Alanları\n- Banyolar, tuvaletler ve duş alanları\n- Mutfaklar ve yemekhane tavanları\n- Çamaşır odaları ve ütü odaları\n- Tesisat şaftları ve bodrum kat hacimleri\n\n3. Yaygın Bir Yanılgı: 'Yeşil Alçıpan Su Geçirmez Değildir'\nYeşil alçıpan neme ve su buharına dirençlidir; ancak 'su yalıtım malzemesi' değildir. Eğer duş içine yeşil alçıpan yapıp üzerine doğrudan seramik yapıştırırsanız, derzlerden sızan su zamanla levhayı çürütür. Duş alanlarındaki yeşil alçıpanın üzerine mutlaka çift kat sürme su yalıtımı ve pah bandı uygulanmalıdır.\n\n4. Montaj Detayları\nYeşil alçıpan montajında standart vidalar paslanabileceği için korozyona dayanıklı fosfat kaplı vidalar ve suya dayanıklı derz dolgu harçları kullanılmalıdır.","image":"assets/blog_28_yesil_alcipan.jpg","date":"01 Aralık 2026","tags":"yeşil alçıpan, banyo, nem, dekorasyon"},{"id":"29","title":"Çatı olukları neden düzenli temizlenmeli?","category":"YALITIM","excerpt":"Tıkalı oluklar cephe, çatı ve temel çevresinde su hasarı oluşturabilir.","content":"Çatı dereleri ve yağmur olukları binanın en görünmeyen ama en ağır yükü taşıyan drenaj elemanlarıdır. Özellikle sonbahar yaprakları, rüzgarla gelen tozlar ve kuş yuvaları olukları tıkayarak kış aylarında felaketlere zemin hazırlar.\n\n1. Suyun Geri Tepmesi ve Saçak Altından İçeri Sızması\nOluk tıkandığında sağanak yağmur suyu tahliye olamaz ve oluktan taşar. Taşma yapan su çatı kalkan duvarlarına, ahşap karkasa ve saçak altı betonuna sızarak dairelerin tavanından içeri damlar.\n\n2. Don Olayları ve Olukların Ağırlıktan Kopması\nTıkanmış bir oluğun içi suyla doluyken don meydana gelirse, olukta yüzlerce kiloluk buz kütlesi oluşur. Bu ağır yük oluk kancalarını büker, asma olukların binadan kopup aşağı düşmesine ve can güvenliği tehlikesine yol açar.\n\n3. Gizli Dere Yalıtımlarının Patlaması\nGizli derelerde bekleyen su zamanla bitümlü membran veya sürme yalıtım tabakasını çürütür. Donma-çözünme döngüsü sırasında buz genleşerek derelerin ek yerlerini yırtar.\n\n4. İdeal Temizlik Takvimi ve Koruyucu Izgaralar\nÇatı olukları yılda en az iki kez (Sonbahar yaprak dökümü sonrası Kasım ayında ve kış çıkışı Mart ayında) temizlenmelidir. İniş borularının ağzına yaprak tutucu plastik süzgeç ızgaraları takılarak iniş borusu tıkanıklıkları tamamen önlenebilir.","image":"assets/blog_29_cati_oluk.jpg","date":"03 Aralık 2026","tags":"çatı, oluk, yağmur suyu, bakım"},{"id":"30","title":"Teras yalıtımında membran mı sürme yalıtım mı?","category":"YALITIM","excerpt":"Sistem seçimi terasın kullanımı, eğimi ve mevcut yüzey durumuna göre yapılır.","content":"Açık teraslar yazın kızgın güneşe, kışın ise kar ve dondurucu soğuğa maruz kaldığı için binanın yalıtım açısından en zorlu alanlarıdır. Teras yalıtımında doğru sistem seçimi hayati önem taşır.\n\n1. Bitümlü Membran Sistemleri\nPetrol türevi bitüm esaslı polyester keçeli membranlar şaloma aleviyle eritilerek zemine yapıştırılır.\n- Avantajları: Yüksek delinme ve yırtılma direnci, kanıtlanmış uzun ömür.\n- Riskleri: Şaloma aleviyle ek yerlerinin kusursuz kaynatılması gerekir; en ufak ek yeri hatası suyun altına yürümesine sebep olur.\n- Kullanım: Genellikle üzerine koruma şapı atılıp seramik kaplanacak teraslarda çift kat olarak uygulanmalıdır.\n\n2. Poliüretan Esaslı Sürme Yalıtımlar\nSıvı halde rulo veya fırçayla sürülen, kuruduğunda eksiz monolitik kauçuksu bir membran oluşturan sistemlerdir.\n- Avantajları: Ek yeri yoktur, parapet dönüşlerine ve süzgeç kenarlarına mükemmel yapışır, %400'e kadar elastiktir.\n- UV Dayanımı: Alifatik poliüretan kaplamalar güneş ışınlarından etkilenmez ve üzerinde doğrudan gezilebilir; seramik kaplama zorunluluğunu ortadan kaldırır.\n\n3. Teras Yalıtımının 3 Altın Kuralı\n- Eğim Şapı: Su terasta asla göllenmemeli, en az %1.5 - 2 meyil ile süzgeçlere akmalıdır.\n- Parapet Dönüşleri: Yalıtım yerde bırakılmamalı, duvar parapetine en az 25-30 cm dikey olarak döndürülmelidir.\n- Çift Kademeli Süzgeç: Hem seramik üstündeki suyu hem de şap altına sızabilecek suyu tahliye eden iki kademeli teras süzgeci kullanılmalıdır.","image":"assets/blog_30_teras_yalitim.jpg","date":"05 Aralık 2026","tags":"teras, membran, su yalıtımı, çatı"},{"id":"31","title":"Ev elektrik tesisatı yenilenirken hangi noktalar kontrol edilmeli?","category":"İNŞAAT","excerpt":"Pano kapasitesi, kaçak akım koruması ve kablo kesitleri güvenli tesisatın temelidir.","content":"Eski binalarda yapılan tadilatlarda estetik işlere öncelik verilirken elektrik tesisatı genellikle ihmal edilir. Oysa 25-30 yıl önceki kablo altyapısı, bugünün kurutma makineleri, bulaşık makineleri, fırınları ve klimalarının çektiği akımı taşıyamaz ve yangın riski oluşturur.\n\n1. Kaçak Akım Koruma Rölesi (Hayat Koruma)\nSigorta kutusunda mutlaka 30 mA Hayat Koruma Kaçak Akım Rölesi bulunmalıdır. Bir kablo soyulduğunda veya cihaz gövdesine elektrik kaçırdığında insanı ölümcül elektrik çarpmasından koruyan tek emniyet kilididir.\n\n2. Kablo Kesitleri ve Halogen-Free Standartları\n- Aydınlatma linye ve sortileri için en az 1.5 mm² bakır kablo\n- Priz hatları için en az 2.5 mm² bakır kablo\nTadilat esnasında yangın anında zehirli gaz çıkarmayan alev iletmez (Halogen-Free) kablolar tercih edilmelidir.\n\n3. Ağır Yük Cihazlarına Bağımsız Linyeler Çekilmeli\nMutfaktaki fırın, bulaşık makinesi, çamaşır makinesi ve klimalar diğer prizlerle aynı hatta bağlanmamalıdır. Her biri için panodan doğrudan eksiz ve bağımsız sigorta hattı çekilmelidir.\n\n4. Topraklama Hattının Varlığı ve Ölçümü\nEski binalarda prizlerde nötr hattı toprağa köprülenmiş (sıfırlama) olabilir; bu durum ölümcül tehlike yaratır. Binanın gerçek topraklama çubuğu ve direnci meger cihazıyla ölçülmeli, tüm prizlere gerçek toprak iletkeni ulaştırılmalıdır.","image":"assets/blog_31_elektrik_tesisati.jpg","date":"07 Aralık 2026","tags":"elektrik tesisatı, tadilat, pano, güvenlik"},{"id":"32","title":"Temiz su tesisatında boru seçimi nasıl yapılır?","category":"İNŞAAT","excerpt":"Basınç, sıcaklık ve kullanım amacına göre doğru boru sistemi belirlenmelidir.","content":"Şapın ve fayansın altında kalan temiz su borularındaki bir sızıntı, tüm banyonun yeniden kırılmasına ve alt kat komşunun tavanının çökmesine yol açar. Temiz su borusu seçimi ve montajında şu kurallara dikkat edilmelidir:\n\n1. PPRC (Polipropilen) Boru Çeşitleri\n- Standart PPRC Borular: Soğuk su hatları için uygundur.\n- Kompozit (Cam Elyaf Takviyeli) Borular: Sıcak su hatlarında mutlaka cam elyaf veya alüminyum folyo takviyeli kompozit borular kullanılmalıdır. Kompozit borular sıcak su geçtiğinde genleşip sarkma ve bükülme yapmaz.\n\n2. PEX (Kılıflı) Boru ve Kollektörlü Sistemler\nYeni nesil projelerde mobil sistem (PEX boru) çok yaygındır. Ana kollektörden her radyatöre ve her musluğa koruyucu spiral kılıf içinden eksiz tek parça boru gider. Boru delinse bile kırma dökme yapmadan kılıfın içinden çekilip yenisi takılabilir.\n\n3. Boru Kaynak Hatası (Aşırı Isıtma)\nPPRC boru kaynağında yapılan en büyük hata, pafta makinesinde boruyu ve manşonu gereğinden fazla eritip içeri doğru itmektir. Bu durumda borunun iç çapı eriyen plastikle tıkanır ve musluktan su basıncı gelmez.\n\n4. Kesinlikle Basınç Testi Yapılmadan Kapatılmamalıdır\nTesisat döşendikten sonra, şap veya fayans yapılmadan önce tesisata su basılarak test pompasıyla en az 10-15 bar basınç altında 24 saat bekletilmelidir. Basınç manometresinde düşme yoksa zemin kapatılabilir.","image":"assets/blog_32_su_borulari.jpg","date":"09 Aralık 2026","tags":"tesisat, pprc, temiz su, tadilat"},{"id":"33","title":"Tadilat sözleşmesinde mutlaka bulunması gereken başlıklar","category":"TADİLAT","excerpt":"Kapsam, süre, ödeme ve teslim şartları yazılı olursa uyuşmazlık riski azalır.","content":"İnşaat ve tadilat sektöründe yaşanan anlaşmazlıkların %90'ı yazılı bir sözleşme yapılmamasından veya sözleşmenin çok yüzeysel hazırlanmasından kaynaklanır. Güvenli bir tadilat için sözleşmede şu maddeler mutlaka yer almalıdır:\n\n1. Ayrıntılı Mahal Listesi ve Marka/Model Şartnamesi\n'Banyo seramiği yapılacaktır' ifadesi geçersizdir. 'Banyo zeminine 60x120 cm Kütahya/Bien marka 1. kalite porselen seramik, çift bileşenli esnek yapıştırıcı ile döşenecektir' şeklinde marka, ebat ve kalite sınıfı açıkça yazılmalıdır.\n\n2. Net Başlangıç ve Teslim Tarihi ile Gecikme Cezası\nİşin fiilen başlayacağı tarih ve teslim edileceği gün net olarak belirtilmelidir. Makul mücbir sebepler dışında geçen her gecikme günü için yükleniciye günlük gecikme cezası (örneğin günlük sabit bir tutar veya toplam bedelin binde biri) konulmalıdır.\n\n3. Kademeli Ödeme Planı (Hakediş Usulü)\nAsla işin başında büyük oranda peşinat ödemeyin!\n- Sözleşme imzasında: %15-20 (Malzeme avansı)\n- Kırım ve kaba tesisat bitiminde: %25\n- Alçı, boya ve seramik bitiminde: %30\n- Montajlar tamamlandığında: %15\n- Eksiksiz teslim ve son kontrolden sonra: Kalan %10\n\n4. Moloz, Temizlik ve Şantiye Güvenliği Sorumluluğu\nApartman ortak alanlarının korunması, molozların belediye kurallarına uygun tahliyesi ve çalışan ustaların iş güvenliği sorumluluğunun yüklenici firmaya ait olduğu belirtilmelidir.\n\n5. Garanti Taahhüdü\nTeslim tarihinden itibaren oluşabilecek işçilik ve tesisat hatalarına karşı en az 1-2 yıl ücretsiz onarım garantisi yazılı hale getirilmelidir.","image":"assets/blog_33_tadilat_sozlesme.jpg","date":"11 Aralık 2026","tags":"tadilat sözleşmesi, teklif, teslim, planlama"},{"id":"34","title":"Yıkım ve moloz yönetimi tadilat bütçesini nasıl etkiler?","category":"TADİLAT","excerpt":"Söküm, taşıma ve atık yönetimi ilk teklif aşamasında açıkça planlanmalıdır.","content":"Ev tadilatına başlarken heyecanla yeni malzemeler seçilir; ancak kapıdan içeri giren ilk ekip kırım ekibidir ve ortaya çıkan moloz dağları çoğu zaman bütçede hesaplanmayan devasa bir masraf yaratır.\n\n1. Yıkım Öncesi Statik Risk Analizi\nAsla projeyi görmeden duvar yıkmayın! Tadilat ustalarının 'bu duvar boşta duruyor' demesiyle kolon, kiriş veya perde betonlar kırılamaz. Taşıyıcı olmayan tuğla bölme duvarlar bile üst katın sehim yapmasını engelliyor olabilir.\n\n2. Kabarma Payı: 1 Metreküp Duvar Kaç Çuval Moloz Eder?\nKatı halde 1 m³ hacme sahip bir tuğla veya beton duvar kırıldığında parçalanıp kabardığı için yaklaşık 1.5 - 1.8 m³ hacme ulaşır. Ortalama bir banyo kırımından 80 ila 120 çuval moloz çıkar. 100 metrekarelik tam daire tadilatında ise 300-400 çuval moloz oluşması sıradandır.\n\n3. Taşıma ve Kat Giderleri\nApartman yönetimi yük asansörü kullanımına izin vermiyorsa, molozların merdivenden çuvallarla indirilmesi ciddi bir işçilik (hamaliye) gerektirir. Yüksek katlı binalarda dış cepheye 'moloz şutu' (plastik döküm borusu) kurmak hem komşuları rahatsız etmez hem de taşıma maliyetini düşürür.\n\n4. Yasal Döküm ve Belediye Harçları\nMolozları yol kenarına veya çöp konteynerine bırakmak ağır para cezalarına tabidir. Belediyelerin lisanslı moloz döküm sahalarına nakliyesi için resmi moloz kamyonu hizmeti alınmalıdır.","image":"assets/blog_34_yikim_moloz.jpg","date":"13 Aralık 2026","tags":"moloz, yıkım, tadilat, nakliye"},{"id":"35","title":"Duvar malzemesi seçerken tuğla mı gazbeton mu?","category":"İNŞAAT","excerpt":"Ağırlık, ısı performansı, ses ve uygulama hızı karar sürecinde birlikte değerlendirilir.","content":"Bölme duvar imalatlarında inşaat dünyasının en çok tartışılan iki malzemesi tuğla ve gazbetondur (Ytong). Projenizin önceliğine göre doğru malzemeyi seçmek maliyeti ve konforu doğrudan belirler.\n\n1. Deprem Güvenliği ve Ağırlık (Ölü Yük)\nGazbeton hacminin %80'i gözenekli havadan oluşan hafif bir yapı malzemesidir. Yoğunluğu tuğlanın neredeyse üçte biri kadardır. Binanın taşıyıcı sistemine ve temeline binen ölü yükü inanılmaz derecede azaltır; bu da deprem anında yapıya gelen sismik kuvveti düşürür.\n\n2. Isı Yalıtım Performansı\nGazbetonun ısı iletkenlik değeri geleneksel tuğlaya göre 3 kat daha iyidir. Dış cephe duvarlarında gazbeton kullanıldığında bina kabuğunun ısı yalıtımına ciddi katkı sağlar.\n\n3. Ses Yalıtımı ve Akustik Performans\nSes yalıtımında temel fizik kuralı kütle kanunudur (ağır malzeme sesi daha iyi tutar). Yoğun delikli kiremit tuğla veya bims bloklar, düşük frekanslı sesleri engellemede hafif gazbetona göre daha başarılıdır. Daireler arası ortak komşu duvarlarda killi tuğla veya sandviç yalıtımlı duvarlar tercih edilmelidir.\n\n4. İşçilik Hızı ve Sıva Ekonomisi\nTuğla harçla örülür, yüzeyi dalgalı kalır ve üzerine kalın kaba sıva + ince sıva yapılması gerekir. Gazbeton ise özel ince yapıştırıcıyla milimetrik örülür; düzgün yüzeyi sayesinde kaba sıvaya gerek kalmadan doğrudan alçı sıva uygulanabilir. Bu durum ciddi zaman ve sıva maliyeti tasarrufu sağlar.","image":"assets/blog_35_tugla_duvar.jpg","date":"15 Aralık 2026","tags":"tuğla, gazbeton, duvar, inşaat"},{"id":"36","title":"Isıcam seçimi faturaları ne kadar etkiler?","category":"YALITIM","excerpt":"Camın ısı geçirgenliği, doğrama kalitesi ve montaj detayları beraber değerlendirilmelidir.","content":"Evlerde kışın yaşanan ısı kaybının ve yazın içeri dolan bunaltıcı sıcağın yaklaşık %25-30'u pencere camlarından kaynaklanır. Standart camlar ile nitelikli kaplamalı camlar arasındaki fark faturalarda doğrudan hissedilir.\n\n1. Standart Çift Cam vs Isıcam Sinerji (Low-E)\nEski tip standart çift camlar sadece iki cam arasındaki hava boşluğu ile yalıtım sağlar. Isıcam Sinerji (Low-E) kaplamalı camların iç yüzeyinde ise gözle görülmeyen mikroskobik metal oksit kaplama bulunur. Bu kaplama içerideki kalorifer ısısını bir ayna gibi içeriye geri yansıtır ve ısı kaybını standart cama göre %50 azaltır.\n\n2. Dört Mevsim Konfor: Isıcam Konfor\nIsıcam Konfor, kışın içerideki ısıyı korurken yazın da güneşin yakıcı ısısını %40 oranında dışarıda tutar. Özellikle güney ve batı cepheli evlerde yaz aylarında klima elektrik tüketimini ciddi ölçüde düşürür.\n\n3. Argon Gaz Dolgusunun Rolü\nCam plakaların arasındaki boşluğa kuru hava yerine argon gazı basılması ısı iletim katsayısını (U değeri) yaklaşık 0.2 - 0.3 W/m²K daha iyileştirir.\n\n4. Üçlü Cam (Triple Glaze) Gerekli mi?\nİç Anadolu, Doğu Anadolu gibi sert kış iklimlerinde üçlü cam (4+12+4+12+4) kullanımı artık bir lüks değil, yatırımı 3-4 yılda amorti eden akıllıca bir tasarruf adımıdır.","image":"assets/blog_36_isicam_pencere.jpg","date":"17 Aralık 2026","tags":"ısıcam, pencere, enerji, yalıtım"},{"id":"37","title":"Daireler arası ses yalıtımı için pratik çözümler","category":"YALITIM","excerpt":"Duvar, tavan ve zemin kaynaklı sesler için farklı detaylar gerekir.","content":"Bitişik nizam dairelerde komşudan gelen konuşma, televizyon sesleri ve tavan vuruntuları modern yaşamın en büyük stres kaynaklarından biridir. Doğru malzeme ve tekniklerle ses yalıtımı sağlamak mümkündür.\n\n1. 'Kütle-Yay-Kütle' Prensibi\nSesi engellemenin tek yolu ses dalgasını sönümlemektir. Mevcut duvara sadece 2 cm strafor veya akustik sünger yapıştırmak sesi KESMEZ. Doğru çözüm; mevcut duvar (kütle), arada 50 mm yüksek yoğunluklu (en az 50-70 kg/m³) taş yünü (yay) ve önünde çift kat akustik alçıpan (kütle) kurmaktır.\n\n2. Titreşim Yalıtımı ve Akustik Bantlar\nAlçıpan karkasını duvara vidalarken sac profillerin altına mutlaka akustik izolasyon bandı çekilmeli, zemin ve tavan bağlantılarında ses köprüsü oluşturulmamalıdır. Vidalar doğrudan duvara titreşim iletmemelidir.\n\n3. Ağır Ses Yalıtım Membranları\nÇift kat alçıpan arasına yerleştirilen 2-3 mm'lik yüksek yoğunluklu EPDM/kauçuk ağır ses bariyerleri levhanın rezonansını öldürür ve ses geçiş kaybını 10-15 dB artırır.\n\n4. Priz Yuvaları ve Tesisat Şaftı Kaçakları\nSes en zayıf bulduğu delikten sızar. Yan yana denk gelen priz yuvaları komşu duvarın sesini doğrudan içeri aktarır. Priz yuvaları arkadan akustik macunlarla doldurulmalı ve delikler yalıtılmalıdır.","image":"assets/blog_37_ses_yalitimi.jpg","date":"19 Aralık 2026","tags":"ses yalıtımı, taş yünü, akustik, duvar"},{"id":"38","title":"Temel perde yalıtımında en sık yapılan hatalar","category":"YALITIM","excerpt":"Toprak altındaki yalıtımda drenaj ve koruma katmanı ihmal edilmemelidir.","content":"Temel ve perde duvarlar bir binanın toprağın altında kalan ve bir daha asla ulaşılamayan kısımlarıdır. Bu alanda yapılacak bir yalıtım hatası, binanın demir donatısının korozyona uğramasına ve betonun çürümesine sebep olur.\n\n1. Soğuk Derz (Pah) Noktalarının Atlanması\nTemel radye plağı ile dikey perde duvarın birleştiği 90 derecelik köşe noktası 'soğuk derz'dir. Bu köşeye pah harcıyla 45 derecelik pah yapılmadan ve su tutucu şişen bantlar yerleştirilmeden yalıtım çekilirse, ilk oturma gerilmesinde yalıtım yırtılır ve su içeri girer.\n\n2. Tie-Rod (Kalıp Mili) Deliklerinin Doldurulmaması\nPerde kalıplarını tutan tie-rod delikleri kaba inşaat sonrası boş kalır. Bu delikler su geçirimsiz rötresiz tamir harçlarıyla ve tıkaçlarla kapatılmazsa, su basıncıyla binaya adeta borudan akar gibi su girer.\n\n3. Drenaj Levhası ile Koruma Yapılmaması\nPerde yalıtımı çekildikten sonra hafriyat toprağı doldurulurken taş ve molozlar yalıtım örtüsünü deler. Yalıtımın üzerine mutlaka kabarcıklı koruma drenaj levhası (ve gerekiyorsa ısı yalıtımı) konulmalıdır.\n\n4. Drenaj Borularının Tıkanması\nTemel çevresine yerleştirilen delikli drenaj boruları geotekstil keçe ile sarılmazsa toprakla dolar ve tıkanır; suyun temele baskı yapmasına neden olur.","image":"assets/blog_38_temel_perde.jpg","date":"21 Aralık 2026","tags":"temel yalıtımı, perde, drenaj, su"},{"id":"39","title":"Şantiyede malzeme depolama neden maliyet kalemidir?","category":"İNŞAAT","excerpt":"Doğru depolama, fireyi, nem hasarını ve iş kaybını azaltır.","content":"Bir şantiyede malzemeyi satın almak kadar, sahada nereye ve nasıl yerleştirdiğiniz de doğrudan kârlılığı etkiler. Yanlış depolanan malzemenin %5 ila %10'u daha kullanılmadan hurdaya çıkar.\n\n1. Çimento, Alçı ve Yapıştırıcı Torbaları\nTorbalı toz ürünler doğrudan beton veya toprak zemine konulmamalıdır. Zeminden rutubet alıp taşlaşmaması için mutlaka ahşap paletler üzerine dizilmeli, yerden en az 10 cm yükseltilmeli ve üzeri su geçirmez brandayla örtülmelidir.\n\n2. İnşaat Demiri Depolama\nDemir çubuklar çamurlu toprağa yatırılmamalıdır. Paslanmayı ve aderansı bozan çamur bulaşmasını önlemek için demirler kalas takozlar üzerine istiflenmelidir.\n\n3. Seramik ve Granit Kolileri\nSeramik kutuları kesinlikle yatay olarak üst üste 6-8 sıradan fazla yığılmamalıdır; alttaki kutular ağırlıktan çatlar. Koliler dik veya dengeli paletli şekilde muhafaza edilmelidir.\n\n4. İki Kez Taşımayı (Çift Elleçleme) Önleyin\nMalzemeyi ileride başka bir imalatın yapılacağı yere indirirseniz, iş başlayınca oradan başka bir yere taşımak zorunda kalırsınız. Çift taşıma hem işçilik zamanını çalar hem de kırılma ve fire oranını ikiye katlar.","image":"assets/blog_39_malzeme_depolama.jpg","date":"23 Aralık 2026","tags":"şantiye, malzeme, depolama, fire"},{"id":"40","title":"Tadilat şantiyesinde iş güvenliği için temel kontrol listesi","category":"İNŞAAT","excerpt":"Küçük işlerde de elektrik, yüksekte çalışma ve toz riskleri yönetilmelidir.","content":"Tadilat işleri 'küçük iş' olarak görüldüğü için iş güvenliği kuralları en çok bu şantiyelerde çiğnenir. Oysa ev tadilatlarında dar alan, toz ve elektrik tehlikeleri bir aradadır.\n\n1. Kişisel Koruyucu Donanım (KKD) Kullanımı\n- Kırım ve kesim işlerinde fırlayan taş parçalarına karşı darbe emici koruyucu gözlük\n- Yoğun tozlu işlerde FFP2/FFP3 toz maskeleri\n- Çivi batmalarına karşı çelik burunlu ve tabanlı iş ayakkabısı\n- Gürültülü kırıcı-delici kullanımında kulaklık\n\n2. Seyyar Elektrik Hatları ve Kablo Güvenliği\nŞantiyede yerlerde sürünen ekli, soyulmuş kablolar ölümcül tehlikedir. Tüm seyyar hatlar kauçuk korumalı ve topraklı olmalı, panoda kaçak akım rölesi devrede bulunmalıdır.\n\n3. Boya ve Tavan Merdivenleri\nKova üstüne kalas koyup tavan boyama devri kapanmalıdır. Düzgün kilitli alüminyum A tipi merdivenler veya tekerlekli seyyar iskeleler kullanılmalıdır.\n\n4. Havalandırma ve Yangın Önlemleri\nTiner bazlı vernik, yapıştırıcı veya sprey boya kullanılan alanlarda kıvılcım çıkaran taşlama yapılmamalı ve alan sürekli pencerelerden havalandırılmalıdır. Şantiyede en az 1 adet 6 kg'lık kuru kimyevi tozlu yangın tüpü hazır bulundurulmalıdır.","image":"assets/blog_40_is_guvenligi.jpg","date":"25 Aralık 2026","tags":"iş güvenliği, şantiye, tadilat, güvenlik"},{"id":"41","title":"Alçıpan bölme duvar planlarken kapı ve tesisat detayları","category":"DEKORASYON","excerpt":"Karkas aralığı, kapı takviyesi ve tesisat geçişleri baştan çözülmelidir.","content":"Büyük bir odayı bölerek giyinme odası veya çalışma alanı oluştururken alçıpan bölme duvarlar en pratik çözümdür. Ancak kapı montajı ve tesisat geçişleri doğru planlanmazsa duvar sallanır ve kapı çarptığında çatlar.\n\n1. Karkas Aks Aralığı (40 cm mi, 60 cm mi?)\nStandart bölme duvarlarda C profilleri 60 cm aralıkla dizilir. Ancak duvarın üzerine seramik kaplanacaksa veya ağır mobilya asılacaksa aks aralığı mutlaka 40 cm'ye düşürülmelidir.\n\n2. Kapı Kasası Çevresinde Güçlendirme\nAlçıpan duvara kapı takıldığında kapının her kapanıp açılmasında dinamik titreşim oluşur. Kapı boşluğunun her iki yanındaki dikey profillerin içine ahşap lata (kalas) veya kutu profil yerleştirilerek tavana ve zemine rijit sabitlenmelidir.\n\n3. Çift Kat Alçıpanın Avantajı\nTek kat alçıpan yumruk atıldığında veya sert bir cisim çarptığında kırılabilir. Duvarın her iki yüzüne çift kat alçıpan (2 x 12.5 mm) vidalanırsa tuğla duvar kadar sağlam ve rijit bir yüzey elde edilir.\n\n4. İç Boşlukta Taş Yünü ve Tesisat\nDuvar karkasının içi boş bırakılırsa duvar davul gibi yankı yapar. Karkas arasına en az 5 cm kalınlığında ses yalıtım taş yünü konulmalı, elektrik boruları profillerdeki özel geçiş deliklerinden geçirilmelidir.","image":"assets/blog_41_alcipan_bolme.jpg","date":"27 Aralık 2026","tags":"alçıpan, bölme duvar, tesisat, dekorasyon"},{"id":"42","title":"Ev tadilatında doğru iş sıralaması nasıl olmalı?","category":"TADİLAT","excerpt":"Kırma, tesisat, sıva, kaplama ve montaj sırası yeniden iş yapma riskini azaltır.","content":"Ev tadilatının kabusa dönmemesi, ekiplerin birbirinin işini bozmaması ve malzemelerin zarar görmemesi için iş sırası kusursuz işletilmelidir. İşte profesyonel tadilat akış şeması:\n\n1. Aşama: Yıkım, Kırım ve Moloz Tahliyesi\nEski banyo, mutfak, seramikler, kaldırılacak duvarlar ve zemin kaplamaları tamamen sökülüp alan tertemiz süpürülür.\n\n2. Aşama: Altyapı İmalatları (Tesisat)\nElektrik borulama ve kablolama, temiz ve pis su boruları, doğalgaz ve kalorifer boruları, klima bakır borulaması duvara ve zemine döşenir.\n\n3. Aşama: Kaba Yüzey Hazırlığı ve Şap\nTesisat kanalları tamir edilir, yeni duvarlar örülür ve zemin teraziye alınarak tesviye şapı dökülür.\n\n4. Aşama: Su Yalıtımı ve Seramik Uygulaması\nŞap kuruduktan sonra banyo ve teraslara sürme su yalıtımı çekilir; ardından duvar ve zemin seramikleri döşenip derzleri verilir.\n\n5. Aşama: Alçıpan Tavan ve Duvar Düzeltme\nAsma tavanlar kapatılır, duvarlara fileli alçı sıva ve saten perdah alçısı çekilip zımparalanır.\n\n6. Aşama: Kapı Kasaları ve Boya 1-2. Kat\nKapı kasaları takılır, tavan ve duvar boyalarının ilk iki katı vurulur.\n\n7. Aşama: Parke Döşemesi ve Süpürgelik\nZemin süpürülüp şilte serilir, laminat parkeler döşenir ve üzeri koruma naylonuyla kapatılır.\n\n8. Aşama: Montajlar (Mutfak, Banyo Dolapları, Vitrifiyeler, Armatürler)\nMutfak dolabı, tezgah, banyo dolabı, klozet, bataryalar, priz anahtarları ve avizeler monte edilir.\n\n9. Aşama: Son Kat Boya Rötuşu ve Detaylı Temizlik\nMobilya montajı sırasında oluşan çizikler boya rötuşuyla giderilir ve ev teslime hazır hale gelir.","image":"assets/blog_42_tadilat_sirasi.jpg","date":"29 Aralık 2026","tags":"tadilat, iş programı, planlama, uygulama"},{"id":"43","title":"Seramik miktarı hesaplarken ne kadar fire bırakılmalı?","category":"SERAMİK","excerpt":"Oda geometrisi, ebat ve desen seçimi seramik sipariş miktarını değiştirir.","content":"Seramik siparişi verirken net zemin alanını ölçüp tam o miktarda sipariş vermek şantiyede işin yarım kalmasının bir numaralı sebebidir. Seramik kesimlerinde kaçınılmaz fire payları vardır.\n\n1. Standart Düz Döşemede Fire Oranı (%7 - %10)\nKare veya dikdörtgen bir odada seramikler duvara paralel düz döşenecekse en az %7 ila %10 fire payı eklenmelidir. Kenar süpürgelikleri ve köşe kesimleri bu paydan karşılanır.\n\n2. Çapraz (Diyagonal) ve Balıksırtı Döşemede Fire Oranı (%15 - %20)\nSeramikler 45 derece açıyla çapraz veya balıksırtı döşenecekse duvar diplerine gelen her seramik üçgen şeklinde kesilmek zorundadır. Bu döşeme modellerinde fire oranı %15'in altına düşmez.\n\n3. Büyük Ebatlı Plakalarda (60x120, 80x160 vb.) Fire Riski\nBüyük porselen plakalarda tek bir kesim hatası yarım metrekarelik seramiğin çöp olmasına neden olur. Boru delikleri, süzgeç yuvaları ve köşe dönüşleri için büyük ebatlarda fire payı yüksek tutulmalıdır.\n\n4. Altın Kural: 1-2 Kutu Yedek Seramik Saklayın\nTadilat bittikten sonra aynı üretim partisinden (Lot / Tonaj numarası) en az 1-2 kutu seramiği bodrumda saklayın. 2 yıl sonra yaşanabilecek bir boru patlamasında veya tadilatta aynı deseni ve tonu piyasada bulmanız imkansızdır.","image":"assets/blog_43_seramik_fire.jpg","date":"31 Aralık 2026","tags":"seramik hesabı, fire, metraj, kaplama"},{"id":"44","title":"Tadilat tekliflerini sağlıklı karşılaştırmanın 5 yolu","category":"TADİLAT","excerpt":"En düşük toplam yerine aynı kapsam ve kalite seviyesini kıyaslayın.","content":"Aynı ev tadilatı için 3 farklı ustayı çağırdınız; biri 200 bin TL, biri 350 bin TL, diğeri 500 bin TL fiyat verdi. En ucuz teklif genellikle en pahalıya mal olur; peki teklifleri nasıl doğru analiz edeceksiniz?\n\n1. Teklif Kalemlerini Birebir Eşleştirin\nDüşük fiyat veren usta çoğu işi teklife dahil etmemiş olabilir. Örneğin 'boya yapılacak' yazmış ama alçı tamiratını, astarı ve kapı boyasını dahil etmemiş olabilir. Tüm kalemlerin kapsamını tek tek karşılaştırın.\n\n2. Malzeme Marka ve Sınıflarını Kontrol Edin\nTeklifte 'seramik dahil' yazması yeterli değildir. Kullanılacak seramik 1. kalite porselen granit mi, yoksa defolu 2. kalite fayans mı? Armatür ECA/Artema mı yoksa markasız ithal ürün mü? Kalite sınıfı fiyatı ikiye katlar.\n\n3. Moloz ve Nakliye Masrafı Kime Ait?\nGenellikle düşük tekliflerde 'moloz atımı işverene aittir' sürprizi çıkar. Moloz nakliyesi ve katlara taşıma işçiliğinin teklif içinde olup olmadığını teyit edin.\n\n4. İş Teslim Süresi ve Ekip Gücü\nİşi 15 günde 4 kişilik profesyonel ekiple bitirecek firma ile tek başına gelip 3 ayda bitirecek ustanın teklifi aynı değerde değildir.\n\n5. PROKONT 2026 Birim Fiyatları ile Doğrulayın\nElinizdeki tekliflerin piyasa rayicine uygun olup olmadığını sitemizdeki Poz Listesi ve Malzeme Karşılaştırma araçlarıyla kontrol ederek fahiş fiyatlardan veya kalitesiz tuzaklardan korunun.","image":"assets/blog_44_teklif_karsilastir.jpg","date":"02 Ocak 2027","tags":"teklif, tadilat, bütçe, karşılaştırma"},{"id":"45","title":"2026 birim fiyatlarıyla çalışma yaparken güncelleme tarihi neden önemlidir?","category":"İNŞAAT","excerpt":"Birim fiyat listelerinin yılı, kurum kaynağı ve revizyon tarihi mutlaka not edilmelidir.","content":"İnşaat ve taahhüt sektöründe maliyet hesapları dinamiktir. Çevre, Şehircilik ve İklim Değişikliği Bakanlığı her yıl güncel birim fiyat ve poz listelerini yayınlar; bu fiyatların güncelliğini takip etmek projelerin başarısını doğrudan belirler.\n\n1. Enflasyon, Döviz ve Enerji Maliyetlerinin Etkisi\nÇimento, demir, bitüm, cam ve alüminyum gibi ana inşaat girdileri enerji ve emtia fiyatlarına doğrudan bağlıdır. 6 ay önceki birim fiyatlarla hazırlanan bir ihale veya tadilat teklifi, iş bittiğinde yüklenicinin veya işverenin ciddi zarara uğramasına yol açar.\n\n2. Resmi Hakedişlerde ve İhalelerde Fiyat Farkı\nKamu ihalelerinde ve kurumsal sözleşmelerde hakedişler ilgili ayın resmi endekslerine ve güncel poz fiyatlarına göre revize edilir. Güncel poz katsayılarını bilmemek hakediş onaylarında kesintilere neden olur.\n\n3. Poz Numaralarındaki Değişiklikler ve Yeni Standartlar\nBakanlık zaman zaman eskiyen imalat pozlarını yürürlükten kaldırır ve yerine yeni çevre dostu veya yüksek performanslı malzemelerin pozlarını ekler (örneğin eski asbestli veya solventli ürünlerin kaldırılıp su bazlı hibrit sistemlerin gelmesi).\n\n4. PROKONT 2026 Poz Veritabanı\nPROKONT sistemi, 2026 yılına ait en güncel birim fiyatları ve poz açıklamalarını anlık olarak barındırır. Teklif hazırlarken veya maliyet analizi yaparken her zaman en son onaylı resmi rakamlarla çalışırsınız.","image":"assets/blog_45_birim_fiyatlar.jpg","date":"04 Ocak 2027","tags":"birim fiyat, poz, 2026, yaklaşık maliyet"},{"id":"46","title":"Poz numarasıyla arama yaparken açıklama nasıl okunmalı?","category":"İNŞAAT","excerpt":"Poz başlığı tek başına yeterli değildir; tarif, birim ve kapsam birlikte incelenmelidir.","content":"Resmi birim fiyat pozları (Örneğin: 15.120.1001 vb.) sadece bir kod ve rakamdan ibaret değildir. Bir pozun açıklama metni, o imalatın sınırlarını, fiyata dahil olan ve hariç tutulan kalemleri belirleyen yasal bir şartnamedir.\n\n1. Poz Açıklamasında 'Her Türlü...' İbaresi\nPoz tarifinde 'Her türlü malzeme ve zayiatı, işçilik, alet ve edevat giderleri, iş yerindeki yükleme, yatay ve düşey taşıma, boşaltma fiyata dahildir' cümlesi yer alıyorsa, yüklenici bu işlemler için ekstra taşıma veya hamaliye parası talep edemez.\n\n2. Ölçü Şekli (Metraj Kriteri)\nPozun altında yer alan 'Ölçü' paragrafı çok dikkatli okunmalıdır. Örneğin seramik kaplama pozunda 'Kaplanan yüzey projesi üzerinden m² olarak hesaplanır, 0.50 m²'den küçük boşluklar düşülmez' gibi özel minha kuralları yer alabilir.\n\n3. Malzemenin Teknik Özellikleri\nPoz açıklamasında malzemenin kalınlığı (örn: 5 cm), yoğunluğu (örn: 150 kg/m³), basma dayanımı (C25/30) veya yangın sınıfı (A1) net olarak belirtilir. Sahada bu şartnameye uymayan daha ucuz bir malzeme kullanılırsa yapı denetim veya kontrol mühendisi imalatı reddeder.\n\n4. PROKONT ile Hızlı Poz Arama\nSitemizdeki Poz Listesi arama motorunda ister poz numarasını ister imalatın adını (örneğin 'taş yünü', 'şap', 'sürme yalıtım') yazarak tüm açıklama metnine ve güncel birim fiyatına saniyeler içinde ulaşabilirsiniz.","image":"assets/blog_46_poz_arama.jpg","date":"06 Ocak 2027","tags":"poz listesi, poz numarası, keşif, metraj"},{"id":"47","title":"Küçük projelerde iş programı hazırlamak neden faydalıdır?","category":"İNŞAAT","excerpt":"Basit bir iş takvimi, ekip ve malzeme çakışmalarını görünür hale getirir.","content":"'İki oda bir salon ev, alt tarafı banyo ve boya yapılacak; ne gerek var iş programına?' düşüncesi, 3 haftada bitebilecek bir tadilatın 3 aya uzamasının ana nedenidir. Küçük projelerde bile iş programı hayat kurtarır.\n\n1. Ekiplerin Çakışmasını ve Birbirini Beklemesini Engeller\nSu tesisatçısı boruları döşemeden seramik ustası gelirse iş yapamaz ve şantiyeyi terk eder. Elektrikçi kabloları çekmeden boyacı alçı çekerse duvarlar yeniden yarılır. İş programı her ustanın sahaya gireceği günü netleştirir.\n\n2. Malzeme Sipariş ve Termin Sürelerini Yönetir\nÖzel üretim mutfak dolapları veya lake iç kapıların fabrikada üretilip teslim edilmesi 3 ila 4 hafta sürer. Kapı siparişini kırım bittiği gün vermezseniz, ev boyandıktan sonra kapıların gelmesini 1 ay boş evde beklersiniz.\n\n3. Nakit Akışını ve Ödemeleri Dengeler\nHangi aşamada ne kadar ödeme yapacağınızı önceden bilirsiniz. Böylece malzeme mağazalarına ve ustalara yapılacak ödemeler sürpriz yaratmaz.\n\n4. Basit Bir Takvim veya Çizelge Yeterlidir\nBüyük inşaat yazılımlarına gerek yoktur; duvarınıza asacağınız basit bir takvim üzerine gün gün hangi ustanın çalışacağını ve hangi malzemenin geleceğini yazmak süreci kusursuz yönetmenizi sağlar.","image":"assets/blog_47_is_programi.jpg","date":"08 Ocak 2027","tags":"planlayıcı, iş programı, şantiye, proje"},{"id":"48","title":"Tadilat tesliminden önce yapılacak son kontrol listesi","category":"TADİLAT","excerpt":"Teslim öncesi detaylı kontrol, küçük eksiklerin büyümeden tamamlanmasını sağlar.","content":"Tadilat bittiğinde ustalara son hakediş ödemesini yapmadan ve anahtarı teslim almadan önce elinize bir not defteri alıp tüm evi adım adım denetlemelisiniz. Bu aşamaya şantiyecilikte 'Eksik ve Kusur Listesi' (Punch List) denir.\n\n1. Islak Hacimler ve Tesisat Testi\n- Tüm lavabo ve evye bataryalarını aynı anda açın; su basıncını ve sıcak suyun gelme süresini kontrol edin.\n- Klozetin sifonunu çekin; altından veya vanasından sızıntı var mı bakın.\n- Duş giderine ve banyo zeminine bir kova su dökün; suyun göllenmeden süzgece doğru akıp akmadığını (meyilini) test edin.\n\n2. Elektrik ve Priz Kontrolü\n- Bir kontrol kalemi veya telefon şarj aletiyle evdeki tüm prizleri tek tek test edin.\n- Tüm anahtarları açıp kapatın; avize, spot ve gizli LED aydınlatmaların sorunsuz yandığını görün.\n\n3. Kapılar ve Pencereler\n- Tüm iç kapıları ve pencereleri sonuna kadar açıp kapatın; kasaya sürtme, kilitlerde takılma veya contalarda hava kaçağı olup olmadığını inceleyin.\n\n4. Boya ve Yüzey Kontrolü\n- Gündüz saatinde perdeleri açıp veya akşam yan ışık (el feneri) tutarak duvarlara bakın. Rulo izi, dalgalanma veya alçı çatlağı olan yerleri kağıt bantla işaretleyin.\n\n5. Derzler ve Silikonlar\n- Süpürgelik arkaları, tezgah kenarları ve duşakabin birleşim yerlerindeki antibakteriyel silikonların eksiksiz çekildiğinden emin olun.","image":"assets/blog_48_teslim_kontrol.jpg","date":"10 Ocak 2027","tags":"teslim, tadilat, kontrol listesi, kalite"},{"id":"49","title":"Kayseri ikliminde dış cephe bakımını ne zaman planlamalı?","category":"YALITIM","excerpt":"Sıcaklık farkları ve yağış dönemleri cephe bakım zamanını etkiler.","content":"Kayseri ve İç Anadolu bölgesi; kışları dondurucu soğuk ve kar yağışlı, yazları ise sıcak ve kurak geçen sert karasal iklim kuşağındadır. Bu iklimde dış cephe boya ve mantolama zamanlaması çok hassas yapılmalıdır.\n\n1. İdeal Uygulama Takvimi (Mayıs - Haziran ve Eylül - Ekim)\nKayseri'de dış cephe çalışmaları için en ideal aylar ilkbahar sonu ve sonbahar başıdır. Gece don tehlikesinin bittiği, gündüz sıcaklığının ise +15°C ile +25°C arasında seyrettiği bu dönemlerde kimyasal harçlar ve boyalar en sağlıklı şekilde priz alır.\n\n2. Gece Don Olayı Tehlikesi (+5°C Kuralı)\nÇimento esaslı mantolama yapıştırıcıları ve su bazlı dış cephe boyaları +5°C'nin altındaki sıcaklıklarda uygulanamaz. Gündüz hava güneşli olsa bile gece sıcaklık eksiye düşerse, harçtaki su donarak kristallere dönüşür ve ilkbaharda sıva pul pul dökülür.\n\n3. Aşırı Temmuz Sıcaklarında Hızlı Kuruma Riski\nYaz ortasında doğrudan güneş alan 40 derecelik cephede sıva veya astar yapılırsa, harç suyunu aniden kaybeder ve plastik büzülme çatlakları oluşur. Çalışma daima gölge takip edilerek yapılmalıdır.\n\n4. Kayseri İklimine Özel Yalıtım Kalınlığı\nKayseri 3. Isı Bölgesi'nde yer alır. Kışın doğalgaz faturalarını düşürmek ve binayı dondan korumak için asgari 6-8 cm kalınlığında karbonlu EPS veya taş yünü tercih edilmelidir.","image":"assets/blog_49_kayseri_cephe.jpg","date":"12 Ocak 2027","tags":"kayseri, dış cephe, bakım, yalıtım"},{"id":"50","title":"İnşaat maliyeti hesaplama aracından verimli sonuç almak için 5 ipucu","category":"İNŞAAT","excerpt":"Doğru ölçü, gerçekçi kalite seçimi ve güncel fiyatlar hesaplamayı güçlendirir.","content":"İnşaat ve tadilat projelerinde gerçekçi bütçe oluşturmak profesyonel planlama gerektirir. PROKONT Akıllı Hesaplama ve Karşılaştırma araçlarından maksimum verimi almak için şu 5 stratejiyi uygulayın:\n\n1. Net ve Brüt Metrekare Ayrımını Netleştirin\nEv veya bina alanını girerken tapudaki brüt alan ile süpürülebilir net alan farkını doğru belirleyin. Duvar kalınlıkları ve balkonlar metrajı etkiler; seramik ve parke hesaplarında net süpürülebilir alanı kullanın.\n\n2. Yapı Kalite Sınıfını Gerçekçi Seçin\nEkonomik, Standart veya Lüks malzeme sınıfları arasında maliyet 2-3 kat fark edebilir. Bütçenize uygun kalite segmentini seçerek ön hesaplama yapın.\n\n3. Malzeme Karşılaştırma Modülünü Aktif Kullanın\nAynı işlevi gören malzemeleri (örneğin EPS vs Taş Yünü, Laminat vs Lamine Parke, Alçıpan vs Gazbeton) yan yana koyarak fiyat/performans kıyaslamasını inceleyin.\n\n4. 2026 Poz Listesi ile Usta Tekliflerini Kıyaslayın\nUstanızdan veya müteahhidinizden aldığınız teklifleri sistemdeki resmi 2026 birim fiyat pozlarıyla karşılaştırarak piyasa rayicinde olup olmadığını hemen teyit edin.\n\n5. %10 Beklenmedik Gider Payını Hesaplamaya Dahil Edin\nHesaplama sonucunda çıkan toplam tutarın üzerine her zaman %10-15 risk payı ekleyerek nihai finansman planınızı yapın.","image":"assets/blog_50_maliyet_araci.jpg","date":"14 Ocak 2027","tags":"maliyet hesaplama, inşaat, bütçe, metraj"}];async function get(){for(let u of['/api/posts','data/posts.json'])try{let r=await fetch(u);if(r.ok)return await r.json()}catch(_){}return JSON.parse(localStorage.getItem('prokont_blog_posts_v2')||JSON.stringify(defaults))}get().then(a=>{let list=document.querySelector('#posts');if(!list){const p=new URLSearchParams(location.search).get('id');if(p){const pt=a.find(x=>x.id===p);if(pt){let d=document.createElement('dialog');d.className='post-dialog';d.innerHTML=`<button class="close-dialog">Kapat ×</button><small>${esc(pt.category)} · ${esc(pt.date)}</small><h2>${esc(pt.title)}</h2><p>${esc(pt.content)}</p>`;document.body.append(d);d.showModal();d.querySelector('button').onclick=()=>d.close();}}return;}let card=p=>`<article class="post-card"><div class="post-image" style="background-image:url('${esc(p.image)}')"></div><div class="post-body"><small>${esc(p.category)} · ${esc(p.date)}</small><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}</p><button data-id="${p.id}">Yazıyı oku →</button></div></article>`,draw=x=>list.innerHTML=x.map(card).join('');draw(a);document.querySelector('#categoryFilters').innerHTML=['Tümü',...new Set(a.map(x=>x.category))].map(x=>`<button>${esc(x)}</button>`).join('');list.onclick=e=>{let p=a.find(x=>x.id===e.target.dataset.id);if(!p)return;let d=document.createElement('dialog');d.className='post-dialog';d.innerHTML=`<button class="close-dialog">Kapat ×</button><small>${esc(p.category)} · ${esc(p.date)}</small><h2>${esc(p.title)}</h2><p>${esc(p.content)}</p>${(p.attachments||[]).map(x=>`<p><a href="${esc(x.url)}" download>📎 ${esc(x.name)}</a></p>`).join('')}`;document.body.append(d);d.showModal();d.querySelector('button').onclick=()=>d.close()};document.querySelector('#blogSearch').oninput=e=>draw(a.filter(x=>(x.title+x.excerpt+x.tags).toLocaleLowerCase('tr').includes(e.target.value.toLocaleLowerCase('tr'))));const p=new URLSearchParams(location.search).get('id');if(p){const btn=list.querySelector(`[data-id="${p}"]`);if(btn)btn.click();}})})();
